INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`locale`,`OptionText`) SELECT b.`MenuID`,b.`OptionID`,'ruRU',IF(MD5(b.`OptionText`)='216993627b637327bc9223d4d789449b','Примите мои извинения. Я не хотел вас обидеть. Я нахожусь здесь по велению моего народа.','') FROM `gossip_menu_option` b WHERE b.`MenuID`=7679 AND b.`OptionID`=0 AND (MD5(b.`OptionText`)='216993627b637327bc9223d4d789449b') ON DUPLICATE KEY UPDATE `OptionText`=IF(VALUES(`OptionText`)<>'' AND COALESCE(`gossip_menu_option_locale`.`OptionText`,'')='',VALUES(`OptionText`),`gossip_menu_option_locale`.`OptionText`);
