INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`RewardText`)='bf53f79e71c8fb3f9865545afa04bf09','Занятно, |3-6($C), чрезвычайно занятно... Кажется, нам еще никогда не приходилось видеть, чтобы мурлоки носили такие украшения.$b$bСудя по тому, что мы знаем об оскверненных кристаллах, мурлок, носивший эту подвеску, полагал, что она дает ему власть над сородичами... Не удивлюсь, если он был много крупнее и сильнее мурлоков своего клана.',''),0 FROM `quest_offer_reward` b WHERE b.`ID`=9576 AND (MD5(b.`RewardText`)='bf53f79e71c8fb3f9865545afa04bf09') ON DUPLICATE KEY UPDATE `RewardText`=IF(VALUES(`RewardText`)<>'' AND COALESCE(`quest_offer_reward_locale`.`RewardText`,'')='',VALUES(`RewardText`),`quest_offer_reward_locale`.`RewardText`);
