INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='275612a3e981e32fe4cb422403b2d817','Больше мощи!',''),IF(MD5(b.`LogDescription`)='f99e6d67f3d5b48e2586c2383fb08005','Зубен Элгенуби хочет, чтобы вы захватили 8 пушек Легиона и принесли их в Штормовую Вершину.',''),IF(MD5(b.`QuestDescription`)='5ff30d3348ad72515eadae5055d1571d','В том, чтобы собирать драгоценный товар мелкими партиями, есть что-то своеобразное, похожее на надомное производство, однако на современном рынке такое производство не выдержит конкуренции.$B$BНет, нам нужен именно массовый способ добычи фаралита! Тогда его количество на рынке будет под нашим полным контролем.$B$BУ меня есть идея, но для ее выполнения потребуется источник мощной, сфокусированной энергии. Есть только одно место, где можно добыть столь мощный источник энергии. Отправляйся в лагеря Легиона к северу отсюда и "позаимствуй" несколько их пушек.',''),IF(MD5(b.`QuestCompletionLog`)='f69a4b993a15a54737739aa55ab401f5','Вернитесь к Зубену Элгенуби на Гиблый пустырь, что в Пустоверти.',''),0 FROM `quest_template` b WHERE b.`ID`=10292 AND (MD5(b.`LogTitle`)='275612a3e981e32fe4cb422403b2d817' OR MD5(b.`LogDescription`)='f99e6d67f3d5b48e2586c2383fb08005' OR MD5(b.`QuestDescription`)='5ff30d3348ad72515eadae5055d1571d' OR MD5(b.`QuestCompletionLog`)='f69a4b993a15a54737739aa55ab401f5') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
