INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='ec22a6c0f967079c794c657d8ccf82c8','Призыв к оружию: Чумные земли!',''),IF(MD5(b.`LogDescription`)='e143fdd1c190d3137fbe7334ab816d33','Разыщите командира Ашлама Неутомимого в Лагере Промозглого Ветра к северу от Альтеракских гор.',''),IF(MD5(b.`QuestDescription`)='559d56162d4f39a850910a983f745ba3','Слушайте все! Все герои – слушайте!$B$BКоролевство Штормграда призывает всех к оружию! Все, кто способен держать в руках оружие, должны подняться на борьбу с проклятой Плетью! Спешите на северные границы Восточных королевств! Новая опасность надвигается из руин Чумных земель!$B$BГерои королевства – собирайтесь к командиру Ашламу Неутомимому в Лагерь Промозглого Ветра к северу от Альтеракских гор!',''),0 FROM `quest_template` b WHERE b.`ID`=10373 AND (MD5(b.`LogTitle`)='ec22a6c0f967079c794c657d8ccf82c8' OR MD5(b.`LogDescription`)='e143fdd1c190d3137fbe7334ab816d33' OR MD5(b.`QuestDescription`)='559d56162d4f39a850910a983f745ba3') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='57d8020015aee343f7d191584f8391a7','Гроза скверноботов',''),IF(MD5(b.`LogDescription`)='fa4ae37e86c07bf311dadfc4aae1dbbb','Поговорите с властителем Ханом Изуверским Кулаком.',''),IF(MD5(b.`QuestDescription`)='c4a5f094758538074da45990a5d27fd4','Властитель Хан Изувер славится своими безумными атаками на Легион, и ему всегда нужны добровольцы. Опредленно, ты ему подходишь.$B$BЕсли считаешь, что у тебя хватит выдержки и безрассудства, пойди и поговори с ним. Он пьет с друзьями вон там, рядом с разбитым скверноботом. Они завалили его всего несколько часов назад. Скажу честно, если бы не Хан, мы все бы здесь полегли.',''),0 FROM `quest_template` b WHERE b.`ID`=10386 AND (MD5(b.`LogTitle`)='57d8020015aee343f7d191584f8391a7' OR MD5(b.`LogDescription`)='fa4ae37e86c07bf311dadfc4aae1dbbb' OR MD5(b.`QuestDescription`)='c4a5f094758538074da45990a5d27fd4') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='57d8020015aee343f7d191584f8391a7','Гроза скверноботов',''),IF(MD5(b.`LogDescription`)='fa4ae37e86c07bf311dadfc4aae1dbbb','Поговорите с властителем Ханом Изуверским Кулаком.',''),IF(MD5(b.`QuestDescription`)='c4a5f094758538074da45990a5d27fd4','Властитель Хан Изувер славится своими безумными атаками на Легион, и ему всегда нужны добровольцы. Опредленно, ты ему подходишь.$B$BЕсли считаешь, что у тебя хватит выдержки и безрассудства, пойди и поговори с ним. Он пьет с друзьями вон там, рядом с разбитым скверноботом. Они завалили его всего несколько часов назад. Скажу честно, если бы не Хан, мы все бы здесь полегли.',''),0 FROM `quest_template` b WHERE b.`ID`=10387 AND (MD5(b.`LogTitle`)='57d8020015aee343f7d191584f8391a7' OR MD5(b.`LogDescription`)='fa4ae37e86c07bf311dadfc4aae1dbbb' OR MD5(b.`QuestDescription`)='c4a5f094758538074da45990a5d27fd4') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='815a3a0298aaa48e877c4c82ae8a3843','Возвращение в Оплот Чести',''),IF(MD5(b.`LogDescription`)='3050c4ce83fb53ca3e14a6452a03b12d','PH: Вернитесь в Оплот Чести',''),IF(MD5(b.`QuestDescription`)='dfb65e48c09d42d31bd3625a05f9ad71','PH: Вернуться в Оплот Чести',''),0 FROM `quest_template` b WHERE b.`ID`=10398 AND (MD5(b.`LogTitle`)='815a3a0298aaa48e877c4c82ae8a3843' OR MD5(b.`LogDescription`)='3050c4ce83fb53ca3e14a6452a03b12d' OR MD5(b.`QuestDescription`)='dfb65e48c09d42d31bd3625a05f9ad71') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`QuestDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='d50c9523aea1ac030ef667654c2ed150','Задание: со щитом или на щите',''),IF(MD5(b.`QuestDescription`)='e426044a48004e964521e72e3fa115b8','Знаешь, что будет, если тебе не удастся перехватить это донесение, $n?$B$B*Назгрел качает головой.*$B$BВ наши ворота постучится вся армия Легиона. И против них у нас не будет ни единого шанса.$B$BСуществует только один способ сделать так, чтобы это письмо не добралось до Передовой Легиона. Тебе придется отправиться к Прудам Аггонара, которые находятся на северо-западе отсюда, и убить Араззиуса.$B$BЕсли тебе это удастся, получишь собственную благодарность Вождя.',''),IF(MD5(b.`QuestCompletionLog`)='7a17296a83d372c92cffdc9595605a9c','Вернитесь к Назгрелу в Каньон Каменной Стены, что на Полуострове Адского Пламени.',''),0 FROM `quest_template` b WHERE b.`ID`=10401 AND (MD5(b.`LogTitle`)='d50c9523aea1ac030ef667654c2ed150' OR MD5(b.`QuestDescription`)='e426044a48004e964521e72e3fa115b8' OR MD5(b.`QuestCompletionLog`)='7a17296a83d372c92cffdc9595605a9c') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='219336f9934849e3b115dd69f04b3aed','Зов Воздуха',''),IF(MD5(b.`LogDescription`)='10231f47603972ef5f1cc98544ba9181','Поговорите с предсказателем Нобундо в Кристальном зале Экзодара на острове Лазурной Дымки.',''),0 FROM `quest_template` b WHERE b.`ID`=10491 AND (MD5(b.`LogTitle`)='219336f9934849e3b115dd69f04b3aed' OR MD5(b.`LogDescription`)='10231f47603972ef5f1cc98544ba9181') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='fb154957f7d66e4ad6dff30e2253e608','Серьезное предложение',''),IF(MD5(b.`LogDescription`)='8d92477486fa47ba1ae5d7646570dc03','Добудьте 15 порций крови животных Зимних Ключей и 20 золотых и отдайте их вместе с наручниками Стихий Делиане в Стальгорне.',''),IF(MD5(b.`QuestDescription`)='548f2f9b0011eec6a667a31a51cbc59d','Добро пожаловать, |3-6($c). У меня найдется кое-что интересное для тебя.$B$BЕсть у меня комплект доспехов – вроде тех, что носят такие как ты, но гораздо лучшего качества. Я бы обменяла наручи из этого комплекта на простые за одну маленькую услугу.$B$BКровь ледопардов и медведей, что водятся в Зимних Ключах, обладает важными свойствами, которые мне сейчас позарез нужны. Принеси мне некоторое количество этой крови, наручи и немного золота. Увидишь – твои старания окупятся.',''),IF(MD5(b.`QuestCompletionLog`)='a16501f59a51a8641c4e2bd0f2e7253a','Вернитесь к Делиане к Высокому трону, что в Стальгорне.',''),0 FROM `quest_template` b WHERE b.`ID`=10492 AND (MD5(b.`LogTitle`)='fb154957f7d66e4ad6dff30e2253e608' OR MD5(b.`LogDescription`)='8d92477486fa47ba1ae5d7646570dc03' OR MD5(b.`QuestDescription`)='548f2f9b0011eec6a667a31a51cbc59d' OR MD5(b.`QuestCompletionLog`)='a16501f59a51a8641c4e2bd0f2e7253a') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND 