INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='fb154957f7d66e4ad6dff30e2253e608','Серьезное предложение',''),IF(MD5(b.`LogDescription`)='070c68a7334771603d9ecd351c6fe182','Добудьте 15 порций яда силитида и 20 золотых и принесите их вместе с наручами из светостали Моквару в Оргриммар.',''),IF(MD5(b.`QuestDescription`)='c890a06c234498cbffba823cd1472913','Привет тебе, |3-6($c)! Судя по тому, как ты держишься, тебе немало довелось повидать на белом свете. Но бьюсь об заклад, что таких доспехов, как эти, тебе видеть не доводилось!$b$bОкажи мне небольшую услугу, и я отдам их тебе в обмен на обычные наручи.$b$bМне нужен яд тварей, обитающих в Силитусе. Принеси мне этот яд и немного золотых монет, и я произведу обмен.',''),0 FROM `quest_template` b WHERE b.`ID`=10493 AND (MD5(b.`LogTitle`)='fb154957f7d66e4ad6dff30e2253e608' OR MD5(b.`LogDescription`)='070c68a7334771603d9ecd351c6fe182' OR MD5(b.`QuestDescription`)='c890a06c234498cbffba823cd1472913') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='c0da2710c892d1c911953da65e2ac06b','Справедливое вознаграждение',''),IF(MD5(b.`LogDescription`)='0bae9342fd089df936efb2e596d43750','Принесите шнурованный ремень Стихий и пару рукавиц Стихий в Стальгорн Делиане.',''),IF(MD5(b.`QuestDescription`)='8ad25fac259a92a3b789d611bd1af83b','Ты $Gсдержал:сдержала; слово и $Gпринес:принесла; устройство Мукса. И уж если я хочу, чтобы ты и дальше $Gзащищал:защищала; мою шкуру, то награда должна быть соответствующей. Принеси мне тот пояс и перчатки, которые хочешь улучшить. Обещаю, что те, которые ты получишь взамен, будут намного лучше.',''),IF(MD5(b.`QuestCompletionLog`)='a16501f59a51a8641c4e2bd0f2e7253a','Вернитесь к Делиане к Высокому трону, что в Стальгорне.',''),0 FROM `quest_template` b WHERE b.`ID`=10494 AND (MD5(b.`LogTitle`)='c0da2710c892d1c911953da65e2ac06b' OR MD5(b.`LogDescription`)='0bae9342fd089df936efb2e596d43750' OR MD5(b.`QuestDescription`)='8ad25fac259a92a3b789d611bd1af83b' OR MD5(b.`QuestCompletionLog`)='a16501f59a51a8641c4e2bd0f2e7253a') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
