INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='ba7c70d7af4383840abf0ba6725972f3','Прощальные слова Антиона',''),IF(MD5(b.`LogDescription`)='de502de611eef02f34625d95c71bad33','Вернитесь в Стальгорн к Делиане с сапогами Стихий, килтом Стихий и наплечьем Стихий.',''),IF(MD5(b.`QuestDescription`)='0e3c124231b518e69f0b249014db02e9','В этом медальоне заключена душа Вальтхалака. В жадности своей мы, безумцы, разделили его на три части, не ведая о поджидавшем нас проклятии.$B$BЕдинственный способ уничтожить заклятье Вальтхалака – вновь собрать медальон. Вернись к Делиане и скажи ей, что Бодли – ее единственная надежда найти остальные части. Поговори с ней об условленной награде.$B$BЯ же ныне спокойно умру. Желаю тебе удачи – она тебе очень понадобится!',''),IF(MD5(b.`QuestCompletionLog`)='a16501f59a51a8641c4e2bd0f2e7253a','Вернитесь к Делиане к Высокому трону, что в Стальгорне.',''),0 FROM `quest_template` b WHERE b.`ID`=10496 AND (MD5(b.`LogTitle`)='ba7c70d7af4383840abf0ba6725972f3' OR MD5(b.`LogDescription`)='de502de611eef02f34625d95c71bad33' OR MD5(b.`QuestDescription`)='0e3c124231b518e69f0b249014db02e9' OR MD5(b.`QuestCompletionLog`)='a16501f59a51a8641c4e2bd0f2e7253a') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`QuestDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='ba7c70d7af4383840abf0ba6725972f3','Прощальные слова Антиона',''),IF(MD5(b.`QuestDescription`)='a80930975e729835f64b9b30af2cf110','В этом амулете хранилась душа Вальтхалака. Мы, по глупости и по жадности, раскололи его на три части, не ведая о проклятии, которое нас ожидало.$b$bЕдинственный способ остановить заклятие Вальтхалака – это снова собрать амулет воедино. Возвращайся к Моквару и скажи ему, что Бодли – его единственная надежда найти оставшиеся части. Расскажи ему про обещанные награды.$b$bНу, а я упокоюсь в мире. Желаю удачи. Она тебе понадобится!',''),IF(MD5(b.`QuestCompletionLog`)='ef486caa427e19173dc479f8433a1228','Вернитесь к Моквару в Оргриммар.',''),0 FROM `quest_template` b WHERE b.`ID`=10497 AND (MD5(b.`LogTitle`)='ba7c70d7af4383840abf0ba6725972f3' OR MD5(b.`QuestDescription`)='a80930975e729835f64b9b30af2cf110' OR MD5(b.`QuestCompletionLog`)='ef486caa427e19173dc479f8433a1228') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='4f07cdb4f50d1b77db9470f48bcbea6f','Сладкое – на закуску',''),IF(MD5(b.`LogDescription`)='254dda090b6b1ab64a0083a65ae5a1da','Отдайте Делиане капюшон Стихий и жилет Стихий.',''),IF(MD5(b.`QuestDescription`)='ba6a164c704e0d0ea01610849568cf09','Замечательная история, $n! Спасибо тебе и сердечная благодарность всем, кто принимал участие. Может, сегодня ночью я хоть нормально посплю.$B$BВ награду хочу предложить несколько вещичек, что тебя, наверное, порадуют.',''),IF(MD5(b.`QuestCompletionLog`)='a16501f59a51a8641c4e2bd0f2e7253a','Вернитесь к Делиане к Высокому трону, что в Стальгорне.',''),0 FROM `quest_template` b WHERE b.`ID`=10498 AND (MD5(b.`LogTitle`)='4f07cdb4f50d1b77db9470f48bcbea6f' OR MD5(b.`LogDescription`)='254dda090b6b1ab64a0083a65ae5a1da' OR MD5(b.`QuestDescription`)='ba6a164c704e0d0ea01610849568cf09' OR MD5(b.`QuestCompletionLog`)='a16501f59a51a8641c4e2bd0f2e7253a') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
