INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='297b54c17861af38ca96a56eb50d9176','Не просто сон',''),IF(MD5(b.`LogDescription`)='9ef5ebb9a6e9374ce85d548ca7260b99','Охраняйте дух Клинтара Странника Снов, пока он будет собирать реликвии Авианы. Потом поговорите с хранителем снов Луросой.',''),IF(MD5(b.`QuestCompletionLog`)='d318907499a53af5bcb5195bd4cbd4e4','Вернитесь к хранителю снов Луросе на Озеро Элуне''ара, что на Лунной поляне.',''),0 FROM `quest_template` b WHERE b.`ID`=10965 AND (MD5(b.`LogTitle`)='297b54c17861af38ca96a56eb50d9176' OR MD5(b.`LogDescription`)='9ef5ebb9a6e9374ce85d548ca7260b99' OR MD5(b.`QuestCompletionLog`)='d318907499a53af5bcb5195bd4cbd4e4') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='36909612810e98dd99065351b1fde1b4','Возвращение к Мортису Шелесту Крыла',''),IF(MD5(b.`LogDescription`)='dd3188e0d5c8f40a27197b960816183e','Отнесите реликвии Авианы Мортису Шелесту Крыла в Кенарийский оплот в Зангартопи.',''),0 FROM `quest_template` b WHERE b.`ID`=10978 AND (MD5(b.`LogTitle`)='36909612810e98dd99065351b1fde1b4' OR MD5(b.`LogDescription`)='dd3188e0d5c8f40a27197b960816183e') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='2ce312c7335ceff8ea2c67a86e9654f4','В Вечную рощу',''),IF(MD5(b.`LogDescription`)='dad9812b23afacdaf648b2b79296410d','Поговорите с Арторн Песней Ветра из Вечной рощи, что в Острогорье.',''),IF(MD5(b.`QuestDescription`)='94ed1aa7cdcaba7ebf5940dfdd7eddf1','Ты $gуверен:уверена;, что $gвидел:видела; именно ворона?$b$bЭто особенно скверно. Мы не сможем помочь Клинтару и Хранителям сна напрямую, но если узнать, кто вмешивается в Изумрудный Сон, можно помешать ему.$b$bДо нас дошли слухи о возрождении в Острогорье древнего культа араккоа – культа бога-ворона. Ступай в Вечную рощу и найди там Арторн Песню Ветра. Может быть, есть какая-то связь между этим культом и Изумрудным Сном.',''),0 FROM `quest_template` b WHERE b.`ID`=10979 AND (MD5(b.`LogTitle`)='2ce312c7335ceff8ea2c67a86e9654f4' OR MD5(b.`LogDescription`)='dad9812b23afacdaf648b2b79296410d' OR MD5(b.`QuestDescription`)='94ed1aa7cdcaba7ebf5940dfdd7eddf1') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='e99f8e35204b5e3224fc31829cd35dfa','Книга Ворона',''),IF(MD5(b.`LogDescription`)='040dace10ea14220c8a65eef5dd30917','Усильте свое зрение при помощи ока летучего ската и камня Провидца и разглядите призраков сторонников культа Ворона. Отыщите на Вершине Смерча старейшину Сай''ккала и расспросите его про книгу Ворона. Затем возвращайтесь к Арторн Песне Ветра.',''),IF(MD5(b.`QuestDescription`)='ffa1ff93a741031b73e37b590230c991','Судя по всему, подозрения Мортиса обоснованы, но убедиться не помешает.$b$bВ ходе своих исследований Времион выяснил, что священным писанием для культа ворона служила некая книга Ворона.$b$bДухи араккоа не захотят являться тебе. Отнеси этот камень в западную часть Острогорья, на вершины, к югу от Леса Ворона. Не забудь добыть око летучего ската. При помощи этих предметов ты сможешь обострить собственное зрение. Отыщи призрака Времиона. Он зовется Старейшина Сай''ккал.',''),0 FROM `quest_template` b WHERE b.`ID`=10980 AND (MD5(b.`LogTitle`)='e99f8e35204b5e3224fc31829cd35dfa' OR MD5(b.`LogDescription`)='040dace10ea14220c8a65eef5dd30917' OR MD5(b.`QuestDescription`)='ffa1ff93a741031b73e37b590230c991') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='2471f255b7c1dc23367abe0eee730244','Поймать скальную пустельгу',''),IF(MD5(b.`LogDescription`)='d294b190dc1eea6516393de61fa1a1eb','Поймайте дикую пустельгу при помощи специальной сети и принесите ее дозорному Элайре на Сумеречную гряду.',''),IF(MD5(b.`QuestDescription`)='86eb2f38a3388e910dcbbdf32e83ef36','Из всех хищных птиц Награнда самое острое зрение у дикой пустельги. Впрочем, из-за небольших размеров этих пичуг их почти повсеместно вытеснили более крупные ветрухи.$b$bПустельга по большей части гнездится здесь, на Сумеречной гряде. Если тебе удастся поймать одну из них, я натаскаю ее на поиски частей закопанной таблички.$b$bВпрочем, поймать ее будет будет нелегко. Пустельга – увертливая птица, и при виде охотника старается убраться подальше. Я предлагаю загнать одну из них в угол или просто подкрасться поближе и накинуть на нее сеть.',''),IF(MD5(b.`QuestCompletionLog`)='c6176033861c2d4cbbf2994dc61b334c','Вернитесь к дозорному Элайре на Сумеречную гряду, что в Награнде.',''),0 FROM `quest_template` b WHERE b.`ID`=10987 AND (MD5(b.`LogTitle`)='2471f255b7c1dc23367abe0eee730244' OR MD5(b.`LogDescription`)='d294b190dc1eea6516393de61fa1a1eb' OR MD5(b.`QuestDescription`)='86eb2f38a3388e910dcbbdf32e83ef36' OR MD5(b.`QuestCompletionLog`)='c6176033861c2d4cbbf2994dc61b334c') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='93e1b8a80873b0d13f6fc94e808ae7bf','Вороньи камни',''),IF(MD5(b.`LogDescription`)='ad6e13689d398424efdaee222e14f7a3','Соберите в Скеттисе 8 вороньих камней и принесите их Арторн Песне Ветра в Вечную рощу в Острогорье.',''),IF(MD5(b.`QuestDescription`)='f077b0f1acdf7be1cd346bcbab0488ee','Я научила твою пустельгу отвечать на свист особого манка. Услышав его, птица слетит к тебе и укажет следующее место, в котором спрятан фрагмент таблички. Арторна сообщила, что искать их следует в Скеттисе, что в юго-восточной части леса Тероккар, так что птица будет ждать тебя там.$b$bКогда ты соберешь все камни, верни манок Арторн, и она позаботится о птичке.$b$bПередай Арторн от меня большой привет.',''),0 FROM `quest_template` b WHERE b.`ID`=10988 AND (MD5(b.`LogTitle`)='93e1b8a80873b0d13f6fc94e808ae7bf' OR MD5(b.`LogDescription`)='ad6e13689d398424efdaee222e14f7a3' OR MD5(b.`QuestDescription`)='f077b0f1acdf7be1cd346bcbab0488ee') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='5159d0b794c05d16aa9bb4f41081705d','Сущность орла',''),IF(MD5(b.`LogDescription`)='5e563a5112f0c1e9002406e62aa41853','Одолейте стража Орла и добудьте у него сущность орла. Призовите пустельгу Арторн особым манком, чтобы сообщить новости об успешном выполнении задания.$b$bЕсли вы потеряете манок Арторн для пустельги, вернитесь к Арторн в Вечную рощу за новым.',''),IF(MD5(b.`QuestDescription`)='24aec68185229f60d07ce4350fe14c1b','Книга Ворона гласит, что его последователи ловили души соперников ворона и заключали их в каменные святилища. К каждому из них был приставлен страж, чтобы никто не вздумал их освободить.$b$bПервое святилище посвящено орлу. Оно находится в холмах на юге от озера Иорун и на западе от Форта Камнеломов в лесу Тероккар.$b$bНа табличке говорится, что орел доблестно бился, но был окружен полчищами врагов. Для этого сражения отлично подойдет обличье медведя.',''),IF(MD5(b.`QuestCompletionLog`)='0b5979655d7fd557dc9f598ceeeee280','Вернитесь к Пустельге Арторн.',''),0 FROM `quest_template` b WHERE b.`ID`=10990 AND (MD5(b.`LogTitle`)='5159d0b794c05d16aa9bb4f41081705d' OR MD5(b.`LogDescription`)='5e563a5112f0c1e9002406e62aa41853' OR MD5(b.`QuestDescription`)='24aec68185229f60d07ce4350fe14c1b' OR MD5(b.`QuestCompletionLog`)='0b5979655d7fd557dc9f598ceeeee280') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='8caef38b6e3eb144b772b1df90b82227','Сущность сокола',''),IF(MD5(b.`LogDescription`)='ce78ff06893366e69afbc3d165970845','Одолейте стража Сокола и добудьте у него сущность сокола. Призовите пустельгу Арторн особым манком, чтобы сообщить новости об успешном выполнении задания.$b$bЕсли вы потеряете манок Арторн для пустельги, вернитесь к Арторн в Вечную рощу за новым.',''),IF(MD5(b.`QuestDescription`)='b81d69b39e969d50dc001c2bab0d955c','*Птица говорит голосом Арторны.*$b$bВторой душой, попавшейся в лапы последователей ворона, стал сокол.$b$bЕго пленили недалеко от Скеттиса, в назидание жрецам ворона.$b$bК северо-западу от Скеттиса, на берегах озера Эре''Нору, находится святилище сокола.$b$bЧтобы одолеть его стража, воспользуйся сильными сторонами сокола. Для этого как нельзя лучше подойдет твой облик кошки. Главное – воспользоваться силой и ловкостью, пока страж не наберется сил!',''),IF(MD5(b.`QuestCompletionLog`)='0b5979655d7fd557dc9f598ceeeee280','Вернитесь к Пустельге Арторн.',''),0 FROM `quest_template` b WHERE b.`ID`=10991 AND (MD5(b.`LogTitle`)='8caef38b6e3eb144b772b1df90b82227' OR MD5(b.`LogDescription`)='ce78ff06893366e69afbc3d165970845' OR MD5(b.`QuestDescription`)='b81d69b39e969d50dc001c2bab0d955c' OR MD5(b.`QuestCompletionLog`)='0b5979655d7fd557dc9f598ceeeee280') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='d57945da4132a8cd074531d2de97b535','Сущность ястреба',''),IF(MD5(b.`LogDescription`)='7d970f4545537463825beab25b9b70b9','Одолейте стража Ястреба и принесите сущность ястреба Арторне Песне Ветра в Вечную рощу.',''),IF(MD5(b.`QuestDescription`)='e38f94bbc2947988efd35706b85570b0','*К вам обращается голос Арторны.*$b$bПоследний и сильнейший из духов, о которых идет речь в книге Ворона. Его пленили далеко от Скеттиса, в святилище на далеком острове на юго-востоке от Аукиндона.$b$bКажется, это описание больше всего подходит к острову, который мы зовем Вершина Крыльев Скорби.$b$bСогласно табличке, страж ястреба практически неуязвим для птичьих когтей. Забудь о грубой силе, обрушь на врага силу звезд. Не повторяй ошибки ястреба.',''),IF(MD5(b.`QuestCompletionLog`)='bf8eb053d5a35898ad98a1b87f55fb96','Вернитесь к Арторн Песне Ветра в Вечную рощу, что в Острогорье.',''),0 FROM `quest_template` b WHERE b.`ID`=10992 AND (MD5(b.`LogTitle`)='d57945da4132a8cd074531d2de97b535' OR MD5(b.`LogDescription`)='7d970f4545537463825beab25b9b70b9' OR MD5(b.`QuestDescription`)='e38f94bbc2947988efd35706b85570b0' OR MD5(b.`QuestCompletionLog`)='bf8eb053d5a35898ad98a1b87f55fb96') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='2418fe32cf3cda63d8b066680d628b5f','Возвращение в Кенарийский оплот',''),IF(MD5(b.`LogDescription`)='8a50701fe0c6daa602c20d62c60f96ef','Отнесите сверток Арторны Мортису Шелесту Крыла в Кенарийский оплот.',''),0 FROM `quest_template` b WHERE b.`ID`=10993 AND (MD5(b.`LogTitle`)='2418fe32cf3cda63d8b066680d628b5f' OR MD5(b.`LogDescription`)='8a50701fe0c6daa602c20d62c60f96ef') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='90f4793c165c5088627927a99eea3b9d','В поисках лунного камня',''),IF(MD5(b.`LogDescription`)='08a51a9186f078f7456e01e6d6fad106','Принесите лунный камень реки Строптивой Мортису Шелесту Крыла в Кенарийский оплот.',''),IF(MD5(b.`QuestDescription`)='7825e9237dd26ba231cf8acbeb5acff1','Если воссоединить эти сущности в редком самоцвете, лунном камне реки Строптивой, ты сможешь вызвать на бой Анзу.$b$bЕсть одно затруднение – такие камни можно найти лишь на стороне Азшары, на скалах рядом с истоком.$b$bПоследняя попытка ночных эльфов добыть эти камни окончилась плачевно. Их лодка все еще стоит на якоре там, где они заметили лунные камни. Смотри в оба и подбирайся к нужному месту по суше, со стороны Азшары.',''),0 FROM `quest_template` b WHERE b.`ID`=10994 AND (MD5(b.`LogTitle`)='90f4793c165c5088627927a99eea3b9d' OR MD5(b.`LogDescription`)='08a51a9186f078f7456e01e6d6fad106' OR MD5(b.`QuestDescription`)='7825e9237dd26ba231cf8acbeb5acff1') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='b4f3caff7a3399c98869c4927241da57','Изгнание бога-ворона',''),IF(MD5(b.`LogDescription`)='8662b053b190ea2c1054d5e177ad241d','Убейте бога-ворона и возвращайтесь к Мортису Шелесту Крыла в Кенарийский оплот.$b$b$B$BЭто задание выполняется в режиме героической сложности.',''),IF(MD5(b.`QuestDescription`)='0f08fba31fbefd9d66d422c64fa942bd','Мы должны, не теряя времени, положить конец бесчинствам бога-ворона. Чтобы выманить его из относительной безопасности Изумрудного Сна, тебе понадобится лунный камень Сущности.$b$bСпустившись в Сетеккские залы, войди в тот зал, что находится перед королевским, и вставь лунный камень в когти ворона.$b$bПусть Анзу поверит, что его призывают в мир последователи. Как только он воплотится, не знай пощады!',''),0 FROM `quest_template` b WHERE b.`ID`=11001 AND (MD5(b.`LogTitle`)='b4f3caff7a3399c98869c4927241da57' OR MD5(b.`LogDescription`)='8662b053b190ea2c1054d5e177ad241d' OR MD5(b.`QuestDescription`)='0f08fba31fbefd9d66d422c64fa942bd') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='429cad6d25ce300640e17bd49a586ac6','[PH] Новые внутренние земли – задание',''),0 FROM `quest_template` b WHERE b.`ID`=11125 AND (MD5(b.`LogTitle`)='429cad6d25ce300640e17bd49a586ac6') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='5c44155666be254da31f71256b3e18c8','<NYI>Тайны Громопойла',''),IF(MD5(b.`LogDescription`)='ca2046dfa221430f6f84bc0890d56e02','Украдите тайный рецепт Мрачнобуха из лагеря Мрачнобуха в Западном Крае и отнесите его Ячменовару на территории Хмельного фестиваля.',''),0 FROM `quest_template` b WHERE b.`ID`=11127 AND (MD5(b.`LogTitle`)='5c44155666be254da31f71256b3e18c8' OR MD5(b.`LogDescription`)='ca2046dfa221430f6f84bc0890d56e02') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`QuestCompletionLog`)='c24837a219b00c9b206c76c0a13dc3c6','Вернитесь к Калии Гастингс на Остров Терамор, что в Пылевых топях.',''),0 FROM `quest_template` b WHERE b.`ID`=11133 AND (MD5(b.`QuestCompletionLog`)='c24837a219b00c9b206c76c0a13dc3c6') ON DUPLICATE KEY UPDATE `QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='5622f17bc15ede8d1222510b1318eefe','Конец вражеской пропаганде',''),IF(MD5(b.`LogDescription`)='b1a5ba50efa13ddfdd7c298c18438693','Арестуйте Гависа Серого Щита, затем доложитесь Калии Гастингс у доков Терамора.',''),IF(MD5(b.`QuestDescription`)='d265cd5b8c30c88f3adfdad77231659e','Теперь, когда мы выжили вражеских подстрекателей из Терамора, пора закончить операцию. Мои местные осведомители доносят, что база вражеской агентуры находится на судне, вставшем на якорь у маленького острова к юго-востоку от доков.$B$BЕсли арестовать их лидера, Гависа Серого Щита, остальные сопротивляться не станут. Найдите его на борту и убедите сдаться. Скорее всего, для виду он немного побрыкается. Но когда поймет, что ему не светит, непременно покорится.',''),0 FROM `quest_template` b WHERE b.`ID`=11134 AND (MD5(b.`LogTitle`)='5622f17bc15ede8d1222510b1318eefe' OR MD5(b.`LogDescription`)='b1a5ba50efa13ddfdd7c298c18438693' OR MD5(b.`QuestDescription`)='d265cd5b8c30c88f3adfdad77231659e') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogDescription`)='ff9e4f9dd853f44dc691f7fd0fb7349c','Принесите набор инструментов и поврежденное снаряжение подводника Ренну Макжабру в Пылевые топи.',''),IF(MD5(b.`QuestDescription`)='b5ddf6095a3c33046974eeb986e3c8a9','Дно отсюда до Алькаца усыпано обломками кораблекрушений. Братство Справедливости уже наняло ныряльщиков, которые рыщут по соседству. Мы добудем их снаряжение, оденем тебя и начнем охоту, но сначала придется кое-что "позаимствовать".$B$BПоищи на этом острове ящик со снаряжением для подводного плавания и что-нибудь для его починки. Когда все найдешь, неси мне, и я за минуту подготовлю тебе костюмчик!',''),0 FROM `quest_template` b WHERE b.`ID`=11139 AND (MD5(b.`LogDescription`)='ff9e4f9dd853f44dc691f7fd0fb7349c' OR MD5(b.`QuestDescription`)='b5ddf6095a3c33046974eeb986e3c8a9') ON DUPLICATE KEY UPDATE `LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogDescription`)='cbe38152dbfe4f2a01444558b72c57b2','Принесите 6 поднятых со дна сундуков Ренну Макжабру в Пылевые топи.',''),IF(MD5(b.`QuestDescription`)='29f87939f4bd45b26fa79b569f01be41','В общем, починил я тебе это снаряжение, так что некоторое время под водой продержишься. Но особо на него не рассчитывай.$B$BОбломки корабля разбросаны по дну – от самого восточного берега этого острова до Алькаца. Покуда хватит воздуха в водолазном шлеме, можешь искать под водой обломки между этим островом и Алькацом. Возьми этот набор для спасения имущества. Не подплывай слишком близко к Алькацу. Тамошние гидры – просто жуть!',''),0 FROM `quest_template` b WHERE b.`ID`=11140 AND (MD5(b.`LogDescription`)='cbe38152dbfe4f2a01444558b72c57b2' OR MD5(b.`QuestDescription`)='29f87939f4bd45b26fa79b569f01be41') ON DUPLICATE KEY UPDATE `LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogDescription`)='aba95caf45219ef982331aac9dff024b','Поговорите в Тераморе с леди Джайной Праудмур.',''),0 FROM `quest_template` b WHERE b.`ID`=11141 AND (MD5(b.`LogDescription`)='aba95caf45219ef982331aac9dff024b') ON DUPLICATE KEY UPDATE `LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogDescription`,`QuestDescription`,`AreaDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogDescription`)='7c52ee0f3d838e429cd54a06d5fe6cba','Поговорите с Коссой Багровое Крыло и возьмите одного из ее грифонов, чтобы обследовать остров Алькац. После выполнения поручения отрапортуйте леди Джайне Праудмур в Тераморе.',''),IF(MD5(b.`QuestDescription`)='570e86db8eb6db56589e0802327e556e','Похоже, догадка Ренна насчет острова Алькац оказалась верной. Нам надо обследовать этот остров, но, чтобы пробиться туда, потребуется целый вооруженный отряд.$B$BОборона Терамора сейчас не может позволить себе такую роскошь, поэтому я договорилась с Коссой Багровое Крыло, ученицей тераморского укротителя грифонов, чтобы она дала тебе одно из своих животных для обследования Алькаца с воздуха.$B$BТолько на острове Алькац можно найти намек на то, что Братство Справедливости причастно к похищению.',''),IF(MD5(b.`AreaDescription`)='99c0d9dec51858f6ad63a9d496b6ac55','Исследуйте остров Алькац.',''),IF(MD5(b.`QuestCompletionLog`)='f947a4003a626d4d63d033b04571ac4a','Вернитесь к леди Джайне Праудмур на Остров Терамор, что в Пылевых топях.',''),0 FROM `quest_template` b WHERE b.`ID`=11142 AND (MD5(b.`LogDescription`)='7c52ee0f3d838e429cd54a06d5fe6cba' OR MD5(b.`QuestDescription`)='570e86db8eb6db56589e0802327e556e' OR MD5(b.`AreaDescription`)='99c0d9dec51858f6ad63a9d496b6ac55' OR MD5(b.`QuestCompletionLog`)='f947a4003a626d4d63d033b04571ac4a') ON DUPLICATE KEY UPDATE `LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`),`AreaDescription`=IF(VALUES(`AreaDescription`)<>'' AND COALESCE(`quest_template_locale`.`AreaDescription`,'')='',VALUES(`AreaDescription`),`quest_template_locale`.`AreaDescription`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogDescription`)='cbdc7388a673dc68f3ea413d4a6da387','Отрапортуйте капитану Дариллу в Северной башне.',''),IF(MD5(b.`QuestDescription`)='31d261637fb3dd17e71448de173ec009','Я говорил с инспектором Таремом по поводу информации, добытой вами в развалинах таверны "Последний привал". Похоже, он уверен, что следы копыт и найденный вами там щит указывают на тауренский клан Зловещий Тотем.$B$BС учетом донесений об их активности на болотах, это вряд ли можно считать простым совпадением. Я отправляю тебя к капитану Дариллу, он у нас что-то вроде специалиста по делам этого клана. Ступай по дороге на север из города к Северной башне. Это вторая застава на дороге.',''),0 FROM `quest_template` b WHERE b.`ID`=11143 AND (MD5(b.`LogDescription`)='cbdc7388a673dc68f3ea413d4a6da387' OR MD5(b.`QuestDescription`)='31d261637fb3dd17e71448de173ec009') ON DUPLICATE KEY UPDATE `LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogDescription`)='cba7941ad4971ffd704abf7fa04ea017','Принесите боевой план племени Зловещий Тотем капитану Дариллу в Северную башню.',''),IF(MD5(b.`QuestDescription`)='cdff8f47d0b9531b11d5635e969a7cb7','Пусть Зловещий Тотем и самое воинственное из тауренских племен, в организованности им не откажешь. Если таверну "Последний привал" подожгли действительно они, приказ об этом мог отдать лишь один из старейшин племени.$B$BНа северо-западе находится одно крупное поселение Зловещего Тотема, деревня Черного Копыта. Она служит им базой для нападений на нашу башню, но я готов поспорить, что там ты найдешь нужную информацию. Планы нападения должны были сохраниться у старейшин деревни.',''),0 FROM `quest_template` b WHERE b.`ID`=11144 AND (MD5(b.`LogDescription`)='cba7941ad4971ffd704abf7fa04ea017' OR MD5(b.`QuestDescription`)='cdff8f47d0b9531b11d5635e969a7cb7') ON DUPLICATE KEY UPDATE `LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogDescription`)='f15d5124fd50975a05a146cec120bcc9','Капитан Дарилл из Северной башни хочет, чтобы вы принесли ему 7 предметов вооружения из деревни Черного Копыта.',''),IF(MD5(b.`QuestDescription`)='e4ebc59815e125393265adc461309977','Если снаряжение, которое ты $gобнаружил:обнаружила; в развалинах таверны, принадлежало воинам Зловещего Тотема, то наверняка в их лагере к северо-западу отсюда найдется еще больше.$B$BНам не удалось собрать достаточно информации о деревне Черного Копыта, но, судя по численности нападавшего отряда, там базируются значительные силы.$B$BСделай все, чтобы заполучить их снаряжение и сравнить с найденным в развалинах таверны.',''),0 FROM `quest_template` b WHERE b.`ID`=11148 AND (MD5(b.`LogDescription`)='f15d5124fd50975a05a146cec120bcc9' OR MD5(b.`QuestDescription`)='e4ebc59815e125393265adc461309977') ON DUPLICATE KEY UPDATE `LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogDescription`)='d2c9dc32ebe1c58c92e375f5258b86ef','Поговорите с Табетой в ее усадьбе.',''),IF(MD5(b.`QuestDescription`)='cb87b15169d9b24c35386bbc37664624','Я не могу выделить никого в помощь второй заставе клана Зловещего Тотема, но, кажется, знаю, кто может помочь вам. $B$BВ самом сердце Трясины, к югу отсюда, находится маленькая усадьба, владеет которой Табета. Она может показаться просто старой отшельницей, но на самом деле она волшебница и провидица, причем небезызвестная. Идите по дороге на юг до ее усадьбы и попросите помощи в поиске тех, кто ответственен за резню в таверне "Последний привал".',''),0 FROM `quest_template` b WHERE b.`ID`=11149 AND (MD5(b.`LogDescription`)='d2c9dc32ebe1c58c92e375f5258b86ef' OR MD5(b.`QuestDescription`)='cb87b15169d9b24c35386bbc37664624') ON DUPLICATE KEY UPDATE `LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogDescription`)='a15cd5192d3b34b471893118278deedf','Сожгите северный, восточный и северо-западный шатры на заставе Дикого Рога, затем вернитесь в усадьбу Табеты.',''),0 FROM `quest_template` b WHERE b.`ID`=11150 AND (MD5(b.`LogDescription`)='a15cd5192d3b34b471893118278deedf') ON DUPLICATE KEY UPDATE `LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogDescription`)='c4ff7af84340448cb7fb4762191ff5d7','Поговорите с капитаном Гарраном Ваймсом в Цитадели в Тераморе.',''),IF(MD5(b.`QuestDescription`)='ca96aafbb3707ce0e8f6bdd7b5c8200a','Хотя, по мне, этот Зловещий Тотем – мухи надоедливые, не более, капитан Ваймс пожелает узнать о ваших делах. Отнесите ему известие, что вы выследили тех, кто замешан в сожжении таверны "Последний привал", и разобрались с ними.$B$BСемье Джима Хьяля это уже не поможет, но хоть в Зловещем Тотеме сто раз подумают, прежде чем лезть на тех, кого защищает Терамор.',''),0 FROM `quest_template` b WHERE b.`ID`=11151 AND (MD5(b.`LogDescription`)='c4ff7af84340448cb7fb4762191ff5d7' OR MD5(b.`QuestDescription`)='ca96aafbb3707ce0e8f6bdd7b5c8200a') ON DUPLICATE KEY UPDATE `LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogDescription`)='2bcbd555afbb59720b1088e22294f71f','Капитан Гарран Ваймс из Цитадели хочет, чтобы вы возложили венок к памятнику семейства Хьяль.',''),IF(MD5(b.`QuestDescription`)='83024e2b139245bb83521e7c561992d5','Как бы дать знать жене и сыну Джеймса Хьяля, что мы отомстили их убийцам?$B$B*Капитан Ваймс достает маленький венок.*$B$BГоворят, что души все видят, даже если мы и не можем говорить с ними. Это малость, но если бы вы возложили этот венок на могилу семейства Хьяль, я был бы вам очень благодарен. Это один из самых больших могильных памятников на кладбище к северу от ворот Терамора.',''),0 FROM `quest_template` b WHERE b.`ID`=11152 AND (MD5(b.`LogDescription`)='2bcbd555afbb59720b1088e22294f71f' OR MD5(b.`QuestDescription`)='83024e2b139245bb83521e7c561992d5') ON DUPLICATE KEY UPDATE `LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogDescription`,`QuestDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogDescription`)='dcd93254893f5014ae124c08d9cbfa48','Отнесите книгу "Подлые обитатели глубин" "Весельчаку" Ленни Полечуду в доки Терамора.',''),IF(MD5(b.`QuestDescription`)='a26f91b58da85629098ca7ea94cd9f30','Чего только не найдешь на старом маяке, знаешь ли. Когда я зажгла фонарь, то увидела вот эту книгу.$B$B<Бабс берет книгу и с выражением читает название.>$B$B"Подлые обитатели глубин!"$B$BНу, такое во сне увидишь – дубиной не отмахаешься! Наверное, стоит ее просмотреть по диагонали, но у меня сейчас совсем нет времени на чтение.$B$BТы, наверное, догадываешься, кому она может понравиться... да, тому рыбнику, "Весельчаку" Ленни Полечуду. Он собирает старые книги.',''),IF(MD5(b.`QuestCompletionLog`)='508b011f54f8139d1c4db77efde0ad28','Поговорите с "Весельчаком" Ленни Полечудом на Острове Терамор, что в Пылевых топях.',''),0 FROM `quest_template` b WHERE b.`ID`=11193 AND (MD5(b.`LogDescription`)='dcd93254893f5014ae124c08d9cbfa48' OR MD5(b.`QuestDescription`)='a26f91b58da85629098ca7ea94cd9f30' OR MD5(b.`QuestCompletionLog`)='508b011f54f8139d1c4db77efde0ad28') ON DUPLICATE KEY UPDATE `LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='f1a2a3e52463aeb5dec9ad2d7a33667f','Игра в куклы',''),IF(MD5(b.`LogDescription`)='f4c8491124377eb29cc6024bdaaa28e8','Отнесите потрепанную куклу вуду Жулю в Шаттрат.',''),0 FROM `quest_template` b WHERE b.`ID`=11195 AND (MD5(b.`LogTitle`)='f1a2a3e52463aeb5dec9ad2d7a33667f' OR MD5(b.`LogDescription`)='f4c8491124377eb29cc6024bdaaa28e8') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogDescription`,`QuestDescription`,`AreaDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogDescription`)='6b751e92adbddc7aedac76011b7fdd5f','Майор Миллз из доков Терамора хочет, чтобы вы покончили с Тетуром.',''),IF(MD5(b.`QuestDescription`)='ac6acb38850bec7e3ea3251fb0114107','Чудовище это или нет, мы не станем рисковать безопасностью наших морских перевозок. Я приказал нашим лучшим стрелкам приготовиться к бою с Тетуром. Артиллеристы усилили оборону доков тремя мортирами.$B$BЯ намерен приказать зажечь маяк. Если Тетур пойдет в атаку, твоя задача будет стрелять из мортир и прикончить тварь прежде, чем он убьет всех наших стрелков. При этом я не стал бы долго стоять на одном месте. Стрельба из мортир обязательно привлечет его внимание.',''),IF(MD5(b.`AreaDescription`)='7876cb8af4f956d3bf071b1b597be2d6','Защитите тераморские доки от Тетура.',''),IF(MD5(b.`QuestCompletionLog`)='b6a629ec98a333f72ea6c979a89f119e','Вернитесь к Майору Миллзу на Остров Терамор, что в Пылевых топях.',''),0 FROM `quest_template` b WHERE b.`ID`=11198 AND (MD5(b.`LogDescription`)='6b751e92adbddc7aedac76011b7fdd5f' OR MD5(b.`QuestDescription`)='ac6acb38850bec7e3ea3251fb0114107' OR MD5(b.`AreaDescription`)='7876cb8af4f956d3bf071b1b597be2d6' OR MD5(b.`QuestCompletionLog`)='b6a629ec98a333f72ea6c979a89f119e') ON DUPLICATE KEY UPDATE `LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`),`AreaDescription`=IF(VALUES(`AreaDescription`)<>'' AND COALESCE(`quest_template_locale`.`AreaDescription`,'')='',VALUES(`AreaDescription`),`quest_template_locale`.`AreaDescription`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogDescription`)='c012bba9f6f0c49a4363f4bb9b993b88','Крог из Деревни Гиблотопь хочет, чтобы вы принесли ему 7 предметов оружия Черного Копыта.',''),IF(MD5(b.`QuestDescription`)='80de5ce7f9f7508c5ec0c2ea01d35ab7','Мы выяснили на пепелище таверны все, что могли. Боюсь представить, куда нас заведет это расследование, но мы должны узнать правду.$B$BСледы копыт и щит с клеймом Мозарна дают повод полагать, что в это дело может быть замешан Зловещий Тотем. Они недавно построили на болотах, к северо-востоку отсюда, поселение, деревню Черного Копыта. Отправляйся туда и поищи еще какое-нибудь оружие работы Мозарна.',''),0 FROM `quest_template` b WHERE b.`ID`=11200 AND (MD5(b.`LogDescription`)='c012bba9f6f0c49a4363f4bb9b993b88' OR MD5(b.`QuestDescription`)='80de5ce7f9f7508c5ec0c2ea01d35ab7') ON DUPLICATE KEY UPDATE `LogDescription`=IF(VALUES(`LogDescription`)<>'' AND (COALESCE(`quest_template_locale`.`LogDescription`,'')='' OR MD5(`quest_template_locale`.`LogDescription`)='c012bba9f6f0c49a4363f4bb9b993b88'),VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND (COALESCE(`quest_template_locale`.`QuestDescription`,'')='' OR MD5(`quest_template_locale`.`QuestDescription`)='80de5ce7f9f7508c5ec0c2ea01d35ab7'),VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogDescription`)='1abee6c5e4a057e0d13dbcaaf7c4fdc5','Принесите боевые планы клана Зловещего Тотема Крогу в Деревню Гиблотопь.',''),IF(MD5(b.`QuestDescription`)='ff930ff1d9a67189391a58507673b89f','Теперь, когда дела племени Зловещего Тотема в Тысяче Игл стали известны всем, многие таурены начали косо смотреть на них. Мы знаем, что вожди племени замешаны в убийстве и похищениях ради достижения своих целей, и я опасаюсь, что следующей их целью станем именно мы.$B$BДеревня Черного Копыта, что на северо-востоке, рядом с Синей топью – новое крупное поселение племени Зловещий Тотем. Их старейшины получают приказы из Громового Утеса. Посмотри, не сумеешь ли ты перехватить приказы и выяснить, что задумывают эти таурены.',''),0 FROM `quest_template` b WHERE b.`ID`=11201 AND (MD5(b.`LogDescription`)='1abee6c5e4a057e0d13dbcaaf7c4fdc5' OR MD5(b.`QuestDescription`)='ff930ff1d9a67189391a58507673b89f') ON DUPLICATE KEY UPDATE `LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogDescription`)='d93de986123f588b8a4f9e329f99516f','Поговорите с Табетой в ее усадьбе на Трясине.',''),IF(MD5(b.`QuestDescription`)='c299d017fc5fd49445f7f26ae63bcb90','Оружие, которое ты $Gзахватил:захватила; в деревне Черного Копыта, никогда не видело других сражений, кроме тренировочного боя, что говорит о том, что Зловещих Тотемов, разрушивших "Последний привал", еще много.$B$BНа юге, в самом сердце Трясины, живет ведьма Табета. Хотя она и человек, но ведет себя с нами по чести и воспитывала некоторых наших магов.$B$BПопроси у нее помощи в поисках Зловещего Тотема, который сжег гостиницу. Альянс не должен считать, что мы замешаны в этом нападении.',''),0 FROM `quest_template` b WHERE b.`ID`=11203 AND (MD5(b.`LogDescription`)='d93de986123f588b8a4f9e329f99516f' OR MD5(b.`QuestDescription`)='c299d017fc5fd49445f7f26ae63bcb90') ON DUPLICATE KEY UPDATE `LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogDescription`)='6be8282d45764df71efa711d0a5c059f','Поговорите с Крогом в Деревне Гиблотопь.',''),IF(MD5(b.`QuestDescription`)='5e63a83c5832ad9af289db5479245e49','Надеюсь, я тебе помог. Увы, больше у меня нет никаких сведений. Мы с учениками сделали столько оружия и доспехов, что всего и не упомнишь.$B$BМы ведь снаряжаем не только отважных бойцов, защищающих земли тауренов, – мои изделия также ценятся среди членов клана Зловещего Тотема. Опытный воин узнает хорошую работу с первого взгляда.',''),0 FROM `quest_template` b WHERE b.`ID`=11204 AND (MD5(b.`LogDescription`)='6be8282d45764df71efa711d0a5c059f' OR MD5(b.`QuestDescription`)='5e63a83c5832ad9af289db5479245e49') ON DUPLICATE KEY UPDATE `LogDescription`=IF(VALUES(`LogDescription`)<>'' AND (COALESCE(`quest_template_locale`.`LogDescription`,'')='' OR MD5(`quest_template_locale`.`LogDescription`)='6be8282d45764df71efa711d0a5c059f'),VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND (COALESCE(`quest_template_locale`.`QuestDescription`,'')='' OR MD5(`quest_template_locale`.`QuestDescription`)='5e63a83c5832ad9af289db5479245e49'),VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogDescription`)='a15cd5192d3b34b471893118278deedf','Сожгите северный, восточный и северо-западный шатры на заставе Дикого Рога, затем вернитесь в усадьбу Табеты.',''),0 FROM `quest_template` b WHERE b.`ID`=11205 AND (MD5(b.`LogDescription`)='a15cd5192d3b34b471893118278deedf') ON DUPLICATE KEY UPDATE `LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogDescription`)='f02e8f2c1e024278321b4c770628102c','Вернитесь к Крогу в Деревню Гиблотопь.',''),0 FROM `quest_template` b WHERE b.`ID`=11206 AND (MD5(b.`LogDescription`)='f02e8f2c1e024278321b4c770628102c') ON DUPLICATE KEY UPDATE `LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogDescription`)='c57c3408e3765a90e660514c5967fb66','Поговорите с майором Миллзом в доках Терамора.',''),IF(MD5(b.`QuestDescription`)='4ea625b204640fb0dccccafbdddd827e','Да, Тетур вполне настоящий, и живет он в тераморских водах.$B$BПриходит на яркий огонь. Именно поэтому маяк там и не зажигают...$B$BСтоит его зажечь, как чудище вернется. Но в здравом уме никто на это не пойдет.$B$BСоответственно, это работка для тебя. Приятно было с тобой выпить, но не обижайся на Ната, если Тетур на самом деле примет тебя за наживку. Если ты намереваешься с ним повидаться, поговори сначала с майором Миллзом из доков Терамора.',''),0 FROM `quest_template` b WHERE b.`ID`=11210 AND (MD5(b.`LogDescription`)='c57c3408e3765a90e660514c5967fb66' OR MD5(b.`QuestDescription`)='4ea625b204640fb0dccccafbdddd827e') ON DUPLICATE KEY UPDATE `LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='7e9a8f34a10e8e19b42ece5a772b8c6f','<NYI> Команда гномов хочет пить',''),IF(MD5(b.`QuestCompletionLog`)='6235abffef06ab5d5dedeaf533eb8309','Вернитесь к начальнику гномского гаража в Тысячу Игл.',''),0 FROM `quest_template` b WHERE b.`ID`=1128 AND (MD5(b.`LogTitle`)='7e9a8f34a10e8e19b42ece5a772b8c6f' OR MD5(b.`QuestCompletionLog`)='6235abffef06ab5d5dedeaf533eb8309') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
