INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='1c144ba5298848c1f2ab182b9e8fbbd3','[ph] Когда я вырасту...',''),IF(MD5(b.`LogDescription`)='50943c44be4a4b6bfc1a3f1c8a88a328','Отведите вашу сиротку, Саландрию, посмотреть на выступление группы L70ETC в Луносвет, на Путь Старейшин. Обязательно позовите Саландрию, если по прибытии ее не окажется рядом.',''),IF(MD5(b.`QuestDescription`)='183797446629833ed24edeec7aedef7a','Когда ты $Gбыл:была; в моем возрасте, ты $Gзнал:знала;, что будешь |3-6($c),\n\n когда вырастешь?$B$BА я не знаю, кем хочу быть. Сначала я хотела быть рыцарем крови, а теперь не хочу. Теперь я хочу быть рок-звездой! Как тот эльф крови из группы L70 ETC!$B$BКогда они не ездят с гастролями, они находятся в Луносвете! Ты отвезешь меня туда? Они обычно на Пути Старейшин, на балконе... Наверное, чтобы фанаты не добрались. Но ведь мы можем попытаться, верно?$B$BНу, пожалуйста, отвези меня туда, ну, пожалуйста!',''),IF(MD5(b.`AreaDescription`)='9d5e23ef5571e0288794b16d265ca426','Саландрия посещает концерт L70ETC в Луносвете',''),IF(MD5(b.`QuestCompletionLog`)='4bde8b81fa8752e12973146533a2e183','Вернитесь к эльфийке крови-сироте.',''),0 FROM `quest_template` b WHERE b.`ID`=11974 AND (MD5(b.`LogTitle`)='1c144ba5298848c1f2ab182b9e8fbbd3' OR MD5(b.`LogDescription`)='50943c44be4a4b6bfc1a3f1c8a88a328' OR MD5(b.`QuestDescription`)='183797446629833ed24edeec7aedef7a' OR MD5(b.`AreaDescription`)='9d5e23ef5571e0288794b16d265ca426' OR MD5(b.`QuestCompletionLog`)='4bde8b81fa8752e12973146533a2e183') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`),`AreaDescription`=IF(VALUES(`AreaDescription`)<>'' AND COALESCE(`quest_template_locale`.`AreaDescription`,'')='',VALUES(`AreaDescription`),`quest_template_locale`.`AreaDescription`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='323976eeece8fcf1949a54a5a7691ee2','zzOLDКарты охотника: меньшие звери',''),IF(MD5(b.`LogDescription`)='19ac166a8467260db401914e067a4f09','Соберите 12 рваных шкур и призовите охотника с помощью карты. Рваные шкуры можно добыть, убивая зверей 5 уровня или выше.',''),IF(MD5(b.`QuestDescription`)='ed30bae3c0e070a7196b96449753e9e9','Вглядевшись в карту, вы внезапно видите себя, $gзакутавшегося:закутавшуюся; в волчьи и медвежьи шкуры. Вы полагаете, что, исполнив это пророчество, можно пробудить истинную силу карты.',''),IF(MD5(b.`QuestCompletionLog`)='ac03a92704737980e444764fe397ab36','Вернитесь к Джонатану Лекрафту на Остров Дизайнера.',''),0 FROM `quest_template` b WHERE b.`ID`=12001 AND (MD5(b.`LogTitle`)='323976eeece8fcf1949a54a5a7691ee2' OR MD5(b.`LogDescription`)='19ac166a8467260db401914e067a4f09' OR MD5(b.`QuestDescription`)='ed30bae3c0e070a7196b96449753e9e9' OR MD5(b.`QuestCompletionLog`)='ac03a92704737980e444764fe397ab36') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='44ec99426387eca09671faf07444b7c3','Месть сладка',''),IF(MD5(b.`LogDescription`)='96c04e578085f394916c400e2496f72b','Добудьте 2 отколотых куска горгульи, убивая горгулий-падальщиков с восточных Полей Падальщиков. Выполнив задачу, вернитесь к лорду Бевису.',''),IF(MD5(b.`QuestDescription`)='5169ef785152245033f5fbcd1adfeb21','Эй, ты... С виду ты вроде $gне дурак:не дура; подраться. Я жажду отомстить Плети, чьи воины убили мою семью. Пойди добудь мне с горгулий пару здоровенных кусков камня, чтобы я мог бросить их на землю и яростно топтать их до тех пор, пока они не рассыплются в гравий, в пыль!$B$BДа. Иди. Убей их.',''),0 FROM `quest_template` b WHERE b.`ID`=12018 AND (MD5(b.`LogTitle`)='44ec99426387eca09671faf07444b7c3' OR MD5(b.`LogDescription`)='96c04e578085f394916c400e2496f72b' OR MD5(b.`QuestDescription`)='5169ef785152245033f5fbcd1adfeb21') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
