INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogDescription`,`QuestDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogDescription`)='ece569032809d7c86ac02d5ebee874f0','Сопроводите посланца Альянса в Среброречье. Выполнив это задание, вернитесь к лейтенанту Думонту в Приют Янтарной Сосны.',''),IF(MD5(b.`QuestDescription`)='ea9a9384e2f032d94419e311c721bdb8','Примерно час назад я должен был отправиться в Среброречье, к северо-западу отсюда, но мой эскорт еще не прибыл.$B$BБудь я проклят, если моя дипломатическая миссия сорвется из-за какого-то проспавшего рекрута!$B$BМы пытаемся наладить связь с местными обитателями, и сейчас каждая минут на счету. Послушай, может быть, ты согласишься сопроводить меня – за определенную плату?',''),IF(MD5(b.`QuestCompletionLog`)='e7ebb0bd9b7d9c41b02002fce86b6b44','Вернитесь к лейтенанту Думонту в Седые холмы.',''),0 FROM `quest_template` b WHERE b.`ID`=12156 AND (MD5(b.`LogDescription`)='ece569032809d7c86ac02d5ebee874f0' OR MD5(b.`QuestDescription`)='ea9a9384e2f032d94419e311c721bdb8' OR MD5(b.`QuestCompletionLog`)='e7ebb0bd9b7d9c41b02002fce86b6b44') ON DUPLICATE KEY UPDATE `LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
