INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='6412cbef5b76a451939da1c04f906193','Огранка камней',''),IF(MD5(b.`LogDescription`)='a54e814628392d253576bc6dfe6c8efd','Принесите два огромных цитрина, два темных нефрита и два сумрачных кристалла Геба''ли в Крепость Песни Войны.',''),IF(MD5(b.`QuestDescription`)='f9904864843feb4df6d74ead74591cab','Добро пожаловать в морозилку, $gдружок:подружка;. Хотя тут не слишком тепло, меня греет моя профессия – огранка камней. Не хватает только материалов!$B$BТы бы $gнашел:нашла; для меня парочку блестяшек – а я бы взамен научил тебя искусству огранки! Тогда ты сможешь получать идеальные камни с улучшенными характеристиками, обрабатывая драгоценные камни Нордскола высокого качества.',''),0 FROM `quest_template` b WHERE b.`ID`=13002 AND (MD5(b.`LogTitle`)='6412cbef5b76a451939da1c04f906193' OR MD5(b.`LogDescription`)='a54e814628392d253576bc6dfe6c8efd' OR MD5(b.`QuestDescription`)='f9904864843feb4df6d74ead74591cab') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND (COALESCE(`quest_template_locale`.`LogTitle`,'')='' OR MD5(`quest_template_locale`.`LogTitle`)='6412cbef5b76a451939da1c04f906193'),VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND (COALESCE(`quest_template_locale`.`LogDescription`,'')='' OR MD5(`quest_template_locale`.`LogDescription`)='a54e814628392d253576bc6dfe6c8efd'),VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND (COALESCE(`quest_template_locale`.`QuestDescription`,'')='' OR MD5(`quest_template_locale`.`QuestDescription`)='f9904864843feb4df6d74ead74591cab'),VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='6412cbef5b76a451939da1c04f906193','Огранка камней',''),IF(MD5(b.`LogDescription`)='90db3b522e925e3ce0fa233cf4a8d978','Принесите два огромных цитрина, два темных нефрита и два сумрачных кристалла Алестосу в Крепость Отваги.',''),IF(MD5(b.`QuestDescription`)='5f30969ae854b30722842d121b60d911','Идет война, и каждый из нас должен внести свой вклад в победу! Я, например, занимаюсь огранкой камней, ибо мне под силу не просто обработать обычный камень, но и превратить его в идеальный. Знаешь, если бы ты $gпринес:принесла; мне несколько необработанных камней, я бы взамен научил тебя искусству огранки! Тогда ты сможешь получать идеальные камни с улучшенными характеристиками, обрабатывая драгоценные камни Нордскола высокого качества.',''),0 FROM `quest_template` b WHERE b.`ID`=13004 AND (MD5(b.`LogTitle`)='6412cbef5b76a451939da1c04f906193' OR MD5(b.`LogDescription`)='90db3b522e925e3ce0fa233cf4a8d978' OR MD5(b.`QuestDescription`)='5f30969ae854b30722842d121b60d911') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='b5233186534eb1ff25f18c6a98206bd1','zzOLDПотерянное устройство',''),IF(MD5(b.`LogDescription`)='13f7668615d96a5ff4f1c10021e7ae62','Почините прибор и верните его Тимоти Джонсу в ювелирный магазин Даларана.',''),IF(MD5(b.`QuestDescription`)='c830da06cd523bded30066eb317b5a85','К обратной стороне устройства прикреплена записка, из которой следует, что его владельцем является некий Тимоти Джонс, имеющий ювелирный магазин в некоем квартале Даларана. Пожалуй, он может вознаградить вас, если вы почините и вернете ему прибор.',''),0 FROM `quest_template` b WHERE b.`ID`=13150 AND (MD5(b.`LogTitle`)='b5233186534eb1ff25f18c6a98206bd1' OR MD5(b.`LogDescription`)='13f7668615d96a5ff4f1c10021e7ae62' OR MD5(b.`QuestDescription`)='c830da06cd523bded30066eb317b5a85') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='4e71e57941a53329fb2e2a01e181df67','Победный трофей: Ингвар Расхититель',''),IF(MD5(b.`LogDescription`)='3883cd2fd0c6d235c59eb60ab25005ae','Принесите секиру Расхитителя верховному магу Лан''далоку, обитающему в Даларане.$B$BЭто задание выполняется в героическом режиме.',''),IF(MD5(b.`QuestDescription`)='58acc3c862d49d39f09bded1ba186da3','Я хочу, чтобы ты $gсобрал:собрала; группу и $gотправился:отправилась; в крепость Утгард. Там тебе предстоит найти и уничтожить Ингвара Расхитителя – прежде, чем он поведет свои войска врайкулов в атаку на ближайшие города Альянса и Орды.$B$BМне потребуется его секира в качестве доказательства того, что с ним покончено. Дело не в том, что я тебе не доверяю. Просто разумно было бы на моем месте убедиться в том, что дело сделано.',''),0 FROM `quest_template` b WHERE b.`ID`=13245 AND (MD5(b.`LogTitle`)='4e71e57941a53329fb2e2a01e181df67' OR MD5(b.`LogDescription`)='3883cd2fd0c6d235c59eb60ab25005ae' OR MD5(b.`QuestDescription`)='58acc3c862d49d39f09bded1ba186da3') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='161a8ca5585530ad5f9f732a00f8d93a','Победный трофей: глашатай Волаж',''),IF(MD5(b.`LogDescription`)='7e7aac6d026cd5253d0a3ffba57de363','Принесите верховному магу Лан''далоку в Даларан усохший мозг безликого.$B$BЭто задание выполняется в героическом режиме.',''),IF(MD5(b.`QuestDescription`)='d84e34568274d9bf57449b54c09ff05e','Нерубы Ан''кахета копали слишком глубоко, пытаясь сбежать от наступающих армий Плети. Они подобрались слишком близко к Древнему богу, влачащему свое существование в глубинах под Нордсколом.$B$BОбнаружив их присутствие, древний бог натравил на них своих безумных созданий, и нерубы попали между вошедшими в поговорку молотом и наковальней.$B$BЛидер сил Древнего бога – глашатай Волаж – одно из кошмарных созданий, известных под именем Безликих. Покончи с ним и принеси мне его усохший мозг.$B$BНо, пожалуйста, постарайся $gсам:сама; не сойти с ума.',''),0 FROM `quest_template` b WHERE b.`ID`=13255 AND (MD5(b.`LogTitle`)='161a8ca5585530ad5f9f732a00f8d93a' OR MD5(b.`LogDescription`)='7e7aac6d026cd5253d0a3ffba57de363' OR MD5(b.`QuestDescription`)='d84e34568274d9bf57449b54c09ff05e') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
