INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='33769123d6fc2e174d9db432f8e71f6e','Курьер из Багрового Легиона',''),IF(MD5(b.`LogDescription`)='0608d88dc9462d5e24e2abecdacd1f7d','Возвращайтесь в Восточные Чумные земли и выследите курьера из Багрового Легиона. Убейте его и заберите приказ верховного рыцаря.$B$BЗа дальнейшими указаниями обращайтесь к Натаносу Гнилостню.',''),IF(MD5(b.`QuestDescription`)='108d75263bd4a1e96ef2c44bf1eb2cf7','Мы не можем напрямую выступить против главнокомандующих Алого ордена – их слишком хорошо охраняют. Однако есть другие способы решения проблемы. Лишившись своей главной силы, они ничего не смогут нам противопоставить.$B$BМои верные ловчие смерти уже давно собирают сведения о деятельности Алого ордена за пределами Стратхольма. Каждый день им присылают инструкции из центрального штаба в Длани Тира. Мы должны перехватить их, |3-6($r)! Убей курьера из Багрового Легиона и забери бумагу. Отдашь ее Натаносу.',''),IF(MD5(b.`QuestCompletionLog`)='b7fa705daf51e452a6e21e1555cd6920','Вернитесь к Натаносу Гнилостню в Поместье Маррисов, что в Восточных Чумных землях.',''),0 FROM `quest_template` b WHERE b.`ID`=14350 AND (MD5(b.`LogTitle`)='33769123d6fc2e174d9db432f8e71f6e' OR MD5(b.`LogDescription`)='0608d88dc9462d5e24e2abecdacd1f7d' OR MD5(b.`QuestDescription`)='108d75263bd4a1e96ef2c44bf1eb2cf7' OR MD5(b.`QuestCompletionLog`)='b7fa705daf51e452a6e21e1555cd6920') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogDescription`)='83f5836f03f84b89fa5d25e1cfa2d0b7','Отнесите запечатанное рекомендательное письмо Дарталии Брагору Кровопалу в Подгород.',''),IF(MD5(b.`QuestDescription`)='c9399e5a2ba671c00c1e2d9e8d31cbf5','Поскольку ты $gпроявил:проявила; немалое мужество и стойкость в битве за Хилсбрад, я написала это рекомендательное письмо, описывающее твой героизм. Пусть его прочитает высшее командование.$B$BОтнеси мое письмо Брагору Кровопалу в Подгород. Можешь гордиться собой, |3-6($c).',''),0 FROM `quest_template` b WHERE b.`ID`=14351 AND (MD5(b.`LogDescription`)='83f5836f03f84b89fa5d25e1cfa2d0b7' OR MD5(b.`QuestDescription`)='c9399e5a2ba671c00c1e2d9e8d31cbf5') ON DUPLICATE KEY UPDATE `LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
