INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='efc6d07e16c63b9dbfcacc1dc04d1d81','Обряды Матери-Земли',''),IF(MD5(b.`LogDescription`)='6ab246d468a7d40647d3bb90015a7856','Бейн Кровавое Копыто из Громового Утеса попросил принести ему рог Арра''чеи.',''),IF(MD5(b.`QuestDescription`)='3284b89e42702fa6084592c1fa474ef4','Ты $gпрошел:прошла; обряды Матери-Земли и $gзаслужил:заслужила; достойное место среди жителей Громового Утеса.$B$BЧтобы сохранить это таким трудом заработанное место, тебе придется и дальше служить своему народу.$b$bМы охотники, $n. Внизу, в Мулгоре, есть могучий кодо по имени Арра''чея. Выследи и убей его, проявив свое искусство охотника, и принеси мне рог Арра''чеи.',''),IF(MD5(b.`QuestCompletionLog`)='77454a16b7f535344c5c0b0ef8fe6e26','Вернитесь к Бейну Кровавому Копыту в Пустоши.',''),0 FROM `quest_template` b WHERE b.`ID`=14440 AND (MD5(b.`LogTitle`)='efc6d07e16c63b9dbfcacc1dc04d1d81' OR MD5(b.`LogDescription`)='6ab246d468a7d40647d3bb90015a7856' OR MD5(b.`QuestDescription`)='3284b89e42702fa6084592c1fa474ef4' OR MD5(b.`QuestCompletionLog`)='77454a16b7f535344c5c0b0ef8fe6e26') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
