INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='bcc274a02f5be252379ce66481073b20','Оборона Черепного вала',''),IF(MD5(b.`LogDescription`)='76893c6bf4e1bea6473965216869b436','Убейте гниющего ледяного великана.',''),IF(MD5(b.`QuestDescription`)='8707323c2a4dfc218077d2437b954549','Это место – какой-то сумасшедший дом! Мало того, что нам приходится воевать с Плетью, так теперь еще эти псы из Альянса кусают нас за бока. Сколько можно воевать на два фронта!$B$BМы прибыли сюда, чтобы обеспечить безопасную высадку наших кораблей, но какое-то гигантское чудовище на другой стороне вала швыряет обломки во все, что движется, и не дает приблизиться малым судам.$B$BСкажу тебе честно – нам с этим громилой не справиться. Одна надежда на тебя и твоих спутников.',''),0 FROM `quest_template` b WHERE b.`ID`=24870 AND (MD5(b.`LogTitle`)='bcc274a02f5be252379ce66481073b20' OR MD5(b.`LogDescription`)='76893c6bf4e1bea6473965216869b436' OR MD5(b.`QuestDescription`)='8707323c2a4dfc218077d2437b954549') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='3487c694b731351c6a07ccd812261fd1','Корни Синелиста',''),IF(MD5(b.`QuestDescription`)='a135895cd994e0289411f4562dee5aec','Корень синелиста – признанный деликатес в любом уголке мира! Но растет он только здесь, в Пустошах, глубоко под землей в Лабиринтах Иглошкурых.$B$BК тому же клубни так сложно найти, если не знать точно где искать! Поэтому я специально надрессировал этих шмыгуносов, чтобы они находили корни под землей. Обоняние у них просто невероятное – они чуют корни с пятидесяти шагов!$B$BЗадачка, конечно, непростая, но если принесешь мне корней, я хорошо заплачу.',''),0 FROM `quest_template` b WHERE b.`ID`=24900 AND (MD5(b.`LogTitle`)='3487c694b731351c6a07ccd812261fd1' OR MD5(b.`QuestDescription`)='a135895cd994e0289411f4562dee5aec') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
