INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='9e170e8df583c6bafd5bf66592d77a1e','Северные фурболги Мертвого Леса',''),IF(MD5(b.`LogDescription`)='c7a8c041ae46a24add8ee2999c9b26e9','Нафиэн просит вас убить 5 дозорного из племени Мертвого Леса, 5 мстителей и 5 шаманов из племени Мертвого Леса.',''),IF(MD5(b.`QuestDescription`)='5a8347d27a5918d63836778ca4d0d782','Прямо на юго-западе отсюда расположен лагерь фурболгов Мертвого Леса. В лагере царствует порча, и я хочу положить этому конец прежде, чем эти фурболги стали настоящей угрозой.$B$BПлемя Мервтого Леса злобное, но это все действие скверны, поразившей их разум. Они не враждебны от природы, но тут уж ничего не поделать. Мне невыносимо тяжело сражаться против собратьев.$B$BПрошу тебя, $n, делай, что должно, но не рассказывай мне подробностей – у меня и без того сердце разрывается.',''),0 FROM `quest_template` b WHERE b.`ID`=6221 AND (MD5(b.`LogTitle`)='9e170e8df583c6bafd5bf66592d77a1e' OR MD5(b.`LogDescription`)='c7a8c041ae46a24add8ee2999c9b26e9' OR MD5(b.`QuestDescription`)='5a8347d27a5918d63836778ca4d0d782') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='2490826e0b35d9cd70d892caab7b4a5c','Боевые действия в деревне Зимней Спячки',''),IF(MD5(b.`LogDescription`)='af07a634980a37c24f27182568f72ad8','Убейте 6 тотемистов, 6 дозорных и 6 землепроходцев из племени Зимней Спячки по просьбе Сальфы.',''),IF(MD5(b.`QuestDescription`)='e25b8da5660b97eb67c05abdfdd19ecf','Клан Древобрюхов готов постоять за себя, $n. В то время как мы позволяем свободно ходить среди нас тем, кому мы доверяем, мы стараемся по возможности избегать общения с другими племенами фурболгов. $b$bПлемя Зимней Спячки в последнее время становится все более враждебным к нам. Они, похоже, впали в состояние ярости, всецело поглощенные собственным страхом и ненавистью ко всему, чего они не понимают. $b$bЕсли бы вы могли сократить их число, это бы нам здорово помогло, $n.',''),0 FROM `quest_template` b WHERE b.`ID`=6241 AND (MD5(b.`LogTitle`)='2490826e0b35d9cd70d892caab7b4a5c' OR MD5(b.`LogDescription`)='af07a634980a37c24f27182568f72ad8' OR MD5(b.`QuestDescription`)='e25b8da5660b97eb67c05abdfdd19ecf') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='6626061daf398452bbc258a65aff6339','Легенды Земли <NYI>',''),IF(MD5(b.`LogDescription`)='febfbc8d708a33f09d4fc6890af82a83','Найдите кристаллы Мизраэль.',''),IF(MD5(b.`QuestDescription`)='d8b4881336d7b936fbe29cac0368f886','В книге идет речь о принцессе элементалей, Мизраэль, и ее заточении глубоко под Нагорьем Арати.$b$bТам же говорится о тайной россыпи кристаллов на нагорье. Эти кристаллы Мизраэль – окна в темницу принцессы.$b$bЕсли отважная душа отыщет эти осколки, быть может, $gон:она; сможет поговорить с Мизраэль...',''),0 FROM `quest_template` b WHERE b.`ID`=636 AND (MD5(b.`LogTitle`)='6626061daf398452bbc258a65aff6339' OR MD5(b.`LogDescription`)='febfbc8d708a33f09d4fc6890af82a83' OR MD5(b.`QuestDescription`)='d8b4881336d7b936fbe29cac0368f886') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND (COALESCE(`quest_template_locale`.`LogTitle`,'')='' OR MD5(`quest_template_locale`.`LogTitle`)='6626061daf398452bbc258a65aff6339'),VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND (COALESCE(`quest_template_locale`.`LogDescription`,'')='' OR MD5(`quest_template_locale`.`LogDescription`)='febfbc8d708a33f09d4fc6890af82a83'),VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND (COALESCE(`quest_template_locale`.`QuestDescription`,'')='' OR MD5(`quest_template_locale`.`QuestDescription`)='d7c41288cc9810ebae2957455c28358b'),VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
