INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='dd1f5eff08c997070bffb5b8094470a1','Благосклонность племени Черного Копья',''),IF(MD5(b.`LogDescription`)='588e765261c20a8e166faf2d6d37f15a','Вам поручили убивать в Альтеракской долине ночных эльфов.$b$bУбив ночного эльфа, вернитесь с его отрубленной головой к Нажьяку Проклятуну в крепость Северного Волка.',''),IF(MD5(b.`QuestDescription`)='2213305744ec2fd75ff54ba5adb96a4a','<Нажьяк ворчит.>$b$bПрежде чем появились ночные эльфы, были тролли. И именно от троллей пошли ночные эльфы. $b$bИх злобные вылазки против моего народа нельзя более терпеть. Олений Шлем хочет стереть нас с лица земли, чтобы не осталось и упоминания о тех, от кого ведут свой род он и его собратья. Не бывать этому! $b$bЗа каждого ночного эльфа, которого ты убьешь и обезглавишь, Надьяк будет одаривать тебя благосклонностью народа Черного Копья. Слава о твоих деяниях распространится по всему Калимдору и Восточным королевствам. Иди же и послужи Черному Копью!',''),0 FROM `quest_template` b WHERE b.`ID`=7361 AND (MD5(b.`LogTitle`)='dd1f5eff08c997070bffb5b8094470a1' OR MD5(b.`LogDescription`)='588e765261c20a8e166faf2d6d37f15a' OR MD5(b.`QuestDescription`)='2213305744ec2fd75ff54ba5adb96a4a') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='d3afb35f2512a9b0cfab427154debcf3','Союзник тауренов',''),IF(MD5(b.`LogDescription`)='020726caa08fd20105924d86bea55a85','Убивайте гномов в Альтеракской долине.$b$bУбив гнома, принесите Раваку Зловещему Тотему в крепость Северного Волка пучок волос гнома.',''),IF(MD5(b.`QuestDescription`)='327e27974df913af70b6c6ceb13d35ff','Мудрая Магата прислала меня в эту зону боевых действий, чтобы изучать другие расы. Точнее, мне поручено собрать образцы тканей гномов. Магату особенно интересует их живучесть. Ведь гномы – эти крошечные, жалкие создания, – проявляют удивительную устойчивость как к боевым ранениям, так и к обычным тяготам жизни.$b$bТебе повезло – мне как раз нужны помощники, чтобы выполнить поручение Магаты. Приноси мне пряди гномьих волос, и таурены будут считать тебя своим союзником.',''),0 FROM `quest_template` b WHERE b.`ID`=7362 AND (MD5(b.`LogTitle`)='d3afb35f2512a9b0cfab427154debcf3' OR MD5(b.`LogDescription`)='020726caa08fd20105924d86bea55a85' OR MD5(b.`QuestDescription`)='327e27974df913af70b6c6ceb13d35ff') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='266374033918ea3688d43db897bc772d','Человечья жизнь',''),IF(MD5(b.`LogDescription`)='0d1d9d0d64deaee9f555bff798d21269','Вам поручили убивать людей в Альтеракской долине.$b$bУбив человека, принесите командору Луи Филипсу (который бродит между линией фронта и крепостью Северного Волка) осколок человеческой кости.$b$bОкончить человеческие страдания совсем несложно!',''),IF(MD5(b.`QuestDescription`)='7749c6e161c96d88f8b061f9f7817412','Люди так отвратительны!$b$b<Командир Филипс брезгливо кривится.>$b$bКонечно, сейчас я состою на службе у клана Северного Волка, и все же я по-прежнему остаюсь слугой Сильваны.$b$bИ в свободное от службы время я подрабатываю, помогая Темным аптекарям Подгорода.$b$bМне поручено собирать осколки человеческих костей, которые будут использованы, чтобы исцелять людей от их жалкого состояния.$b$bЯ также могу давать аналогичное поручение своим подчиненным.$b$bИщите их. Убивайте их. И приносите мне осколки их костей!',''),0 FROM `quest_template` b WHERE b.`ID`=7363 AND (MD5(b.`LogTitle`)='266374033918ea3688d43db897bc772d' OR MD5(b.`LogDescription`)='0d1d9d0d64deaee9f555bff798d21269' OR MD5(b.`QuestDescription`)='7749c6e161c96d88f8b061f9f7817412') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='a336daa77e5a9447dfe67d2cb7da06f3','Ремесленники по чешуе',''),IF(MD5(b.`LogDescription`)='ed0fcde8bff8c8fe847b487cf3c2269e','Соберите немного чешуи для Караны из Убежища на Болоте Печали.',''),IF(MD5(b.`QuestDescription`)='3d48f160ad5d654c191b4f43051b9814','Принеси мне немного чешуи',''),IF(MD5(b.`QuestCompletionLog`)='aa6f1f1531fd18d5f914bd7ec8b902d2','Вернитесь к Каране в Убежище, что на Болоте Печали.',''),0 FROM `quest_template` b WHERE b.`ID`=7384 AND (MD5(b.`LogTitle`)='a336daa77e5a9447dfe67d2cb7da06f3' OR MD5(b.`LogDescription`)='ed0fcde8bff8c8fe847b487cf3c2269e' OR MD5(b.`QuestDescription`)='3d48f160ad5d654c191b4f43051b9814' OR MD5(b.`QuestCompletionLog`)='aa6f1f1531fd18d5f914bd7ec8b902d2') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
