INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogDescription`,`LogTitle`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogDescription`)='825e745d6fb50d1e31a22e67d081ed81','Принесите скальп тенелова Маурину Костолому в Пустоши.',''),IF(MD5(b.`LogTitle`)='d499ad7309e1f61f2489a96287939f56','Награда за фурболгов Кривой Сосны',''),IF(MD5(b.`QuestDescription`)='03b59b06e2f6fd9ead959ee7b99718a8','Пожалуй, я сумею отыскать этого повелителя демонов, если найду нужные реагенты.$B$BОднако, если он действительно так могуществен, мне понадобятся предметы, собранные со смертельно опасных тварей...$B$BПрежде всего мне придется снять заклятия, которые защищают его от соглядатаев. Для этого нужен скальп сатира, но не первого попавшегося, а тенелова из племени Ярой Ненависти.$B$BИщи их в древних развалинах на северо-востоке Пустошей.',''),0 FROM `quest_template` b WHERE b.`ID`=8458 AND (MD5(b.`LogDescription`)='825e745d6fb50d1e31a22e67d081ed81' OR MD5(b.`LogTitle`)='d499ad7309e1f61f2489a96287939f56' OR MD5(b.`QuestDescription`)='03b59b06e2f6fd9ead959ee7b99718a8') ON DUPLICATE KEY UPDATE `LogDescription`=IF(VALUES(`LogDescription`)<>'' AND (COALESCE(`quest_template_locale`.`LogDescription`,'')='' OR MD5(`quest_template_locale`.`LogDescription`)='cee0b9f60d3551bcbd2e71bda7af8048'),VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`LogTitle`=IF(VALUES(`LogTitle`)<>'' AND (COALESCE(`quest_template_locale`.`LogTitle`,'')='' OR MD5(`quest_template_locale`.`LogTitle`)='dc0c478f4dd40b5618c1ee8c86966310'),VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND (COALESCE(`quest_template_locale`.`QuestDescription`,'')='' OR MD5(`quest_template_locale`.`QuestDescription`)='e1043a8f0ad8bfa5bb47986b66f6d22a'),VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
