INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='ba7c70d7af4383840abf0ba6725972f3','Прощальные слова Антиона',''),IF(MD5(b.`LogDescription`)='d0b4c6e5e95786d6dc64ca6240ea73c7','Поговорите с Делианой из Стальгорна.',''),IF(MD5(b.`QuestDescription`)='8f596438c3ca7dcf9cff9c64da4c2a18','В этом амулете хранилась душа Вальтхалака. Мы, по глупости и по жадности, раскололи его на три части, не ведая о проклятии, которое нас ожидало.$b$bЕдинственный способ остановить заклятие Вальтхалака – это снова собрать амулет воедино. Возвращайся к Делиане и скажи ей, что Бодли – ее единственная надежда найти оставшиеся части. $b$bНу, а я упокоюсь в мире. Желаю удачи. Она тебе понадобится!',''),0 FROM `quest_template` b WHERE b.`ID`=9030 AND (MD5(b.`LogTitle`)='ba7c70d7af4383840abf0ba6725972f3' OR MD5(b.`LogDescription`)='d0b4c6e5e95786d6dc64ca6240ea73c7' OR MD5(b.`QuestDescription`)='8f596438c3ca7dcf9cff9c64da4c2a18') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='9850af1cb918c2b8a151c324293f584c','<TXT>Прощальные слова Антиона',''),IF(MD5(b.`LogDescription`)='ff84640346c0c93ba2aa1d8298fde7af','Поговорите с Мокваром из Оргриммара.',''),IF(MD5(b.`QuestDescription`)='8f596438c3ca7dcf9cff9c64da4c2a18','В этом амулете хранилась душа Вальтхалака. Мы, по глупости и по жадности, раскололи его на три части, не ведая о проклятии, которое нас ожидало.$b$bЕдинственный способ остановить заклятие Вальтхалака – это снова собрать амулет воедино. Возвращайся к Делиане и скажи ей, что Бодли – ее единственная надежда найти оставшиеся части. $b$bНу, а я упокоюсь в мире. Желаю удачи. Она тебе понадобится!',''),0 FROM `quest_template` b WHERE b.`ID`=9031 AND (MD5(b.`LogTitle`)='9850af1cb918c2b8a151c324293f584c' OR MD5(b.`LogDescription`)='ff84640346c0c93ba2aa1d8298fde7af' OR MD5(b.`QuestDescription`)='8f596438c3ca7dcf9cff9c64da4c2a18') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
