INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='1abc37ab37354bb8dc0035fa600c0be7','Знакомство с Альянсом',''),IF(MD5(b.`LogDescription`)='85ddf023cbb632016302fac244eac6e8','Получите дальнейшие указания у Рандала Эмерсона в крепости Штормграда, а затем найдите короля Магни Бронзоборода, главного механика Меггакрута и Тиранду Шелест Ветра и поговорите с ними.',''),IF(MD5(b.`QuestDescription`)='9a8ce047532760dcb3842df2a02c2155','В каждом из наших городов – Штормграде, Стальгорне и Дарнасе – обитают разные народы с уникальной культурой. Раз уж ты в гостях у Альянса здесь, на Азероте, выдели время для того, чтобы по очереди посетить каждую из наших столиц.\n\nДля начала поговори с Рандалом Эмерсоном в южном вестибюле – он укажет тебе дорогу.',''),0 FROM `quest_template` b WHERE b.`ID`=93963 AND (MD5(b.`LogTitle`)='1abc37ab37354bb8dc0035fa600c0be7' OR MD5(b.`LogDescription`)='85ddf023cbb632016302fac244eac6e8' OR MD5(b.`QuestDescription`)='9a8ce047532760dcb3842df2a02c2155') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
