INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='6f80a98d12af069ace1cbebf6ed2a575','Дорога в Астранаар',''),IF(MD5(b.`LogDescription`)='9f94a0ca85f6e47b75d161e142b7d44e','Отправляйтесь в Астранаар в Ясеневом лесу и поговорите с воздаятельницей Паланаарой.',''),IF(MD5(b.`QuestDescription`)='ceb04c52bd7295f9c6b6ae238e0c633d','Я рад, что ты $gпришел:пришла; на помощь. Тут тебе и правда найдется дело.$B$BМне хотелось бы, чтобы ты $gотправился:отправилась; в городок ночных эльфов Астранаар. Он расположен в Ясеневом лесу, огромном лесу к югу от Темных берегов в Калимдоре.$B$BПожалуйста, поговори с воздаятельницей Паланаарой, когда прибудешь туда, и посмотри, чем сможешь помочь местным жителям.',''),0 FROM `quest_template` b WHERE b.`ID`=9432 AND (MD5(b.`LogTitle`)='6f80a98d12af069ace1cbebf6ed2a575' OR MD5(b.`LogDescription`)='9f94a0ca85f6e47b75d161e142b7d44e' OR MD5(b.`QuestDescription`)='ceb04c52bd7295f9c6b6ae238e0c633d') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
