INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='d94b8b34d992ad3165a550e982d454c2','Зов Воды',''),IF(MD5(b.`LogDescription`)='87e737d3a25986e3427a85ac4fcc5ff8','Найдите Норрика Тана Лока в Лок Модане.',''),IF(MD5(b.`QuestDescription`)='63066bce41563db0f3619da7bb066ef3','Много воды утекло со времени последнего испытания, $n. Ты $gпроявил:проявила; немало упорства в учении, но теперь тебе пришло время узнать о чистоте воды.\n\nОтыщи Норрика Тана Лока. Он живет у северо-западного края озера, к югу от Каменной Плотины. Там и найдешь его землянку. Удачи тебе, $n.',''),0 FROM `quest_template` b WHERE b.`ID`=94494 AND (MD5(b.`LogTitle`)='d94b8b34d992ad3165a550e982d454c2' OR MD5(b.`LogDescription`)='87e737d3a25986e3427a85ac4fcc5ff8' OR MD5(b.`QuestDescription`)='63066bce41563db0f3619da7bb066ef3') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='d94b8b34d992ad3165a550e982d454c2','Зов Воды',''),IF(MD5(b.`LogDescription`)='2f9bc0c792e0b265e66514fd4876d30d','Найдите Гервдану Саэгрунд в Болотине.',''),0 FROM `quest_template` b WHERE b.`ID`=94495 AND (MD5(b.`LogTitle`)='d94b8b34d992ad3165a550e982d454c2' OR MD5(b.`LogDescription`)='2f9bc0c792e0b265e66514fd4876d30d') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='d94b8b34d992ad3165a550e982d454c2','Зов Воды',''),IF(MD5(b.`LogDescription`)='e507d31a4176653730c5f438eb6562fe','Наполните пустой коричневый бурдюк для воды у подножия водопадов под пещерой Гервданы в Болотине и отнесите ей воду.',''),0 FROM `quest_template` b WHERE b.`ID`=94497 AND (MD5(b.`LogTitle`)='d94b8b34d992ad3165a550e982d454c2' OR MD5(b.`LogDescription`)='e507d31a4176653730c5f438eb6562fe') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='d94b8b34d992ad3165a550e982d454c2','Зов Воды',''),IF(MD5(b.`LogDescription`)='29360b581c9ef64b548f8b44b1ccad97','Наполните пустой красный бурдюк для воды из водопада Каменной Стражи неподалеку от мурлоков-следопытов и отнесите воду Гервдане Саэгрунд в Болотину.',''),IF(MD5(b.`QuestDescription`)='876288291e6917cbdc1e95295cf81381','Озеро Безмолвия поит все Красногорье, но к тому времени как его воды обрушиваются в водопаде Каменной Стражи, к ним что-то примешивается. Местные мурлоки – здоровенные и странные твари, совсем не такие, как те, которых можно найти здесь или у озера Лок. К счастью для горожан, они почти не отходят от подножия водопада.\n\nПринеси мне образец вод у того старого форта. Хочу разобраться, что их загрязняет, – яд или что-то еще.',''),0 FROM `quest_template` b WHERE b.`ID`=94499 AND (MD5(b.`LogTitle`)='d94b8b34d992ad3165a550e982d454c2' OR MD5(b.`LogDescription`)='29360b581c9ef64b548f8b44b1ccad97' OR MD5(b.`QuestDescription`)='876288291e6917cbdc1e95295cf81381') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='299e65bc4ecc12587d5ce0ad2a39c8d7','Зов Земли',''),IF(MD5(b.`LogDescription`)='f8db05f5cd3da8e7d66c086968f8b1f7','Убейте 4 неупокоенных духов земли и возвращайтесь к духу долины в Священную рощу долины Аммен.',''),IF(MD5(b.`QuestDescription`)='a5c7a1fc70b3fdd1bd22d3bf0f0c16db','Крушение корабля дренеев привело к нарушению природного равновесия в этой долине. Духи Земли в ярости обратились против других стихий, пытающихся утихомирить их. Вскоре ты поймешь, как важна гармония стихий для их познания.$b$bИтак, я поручаю тебе восстановить исконное равновесие. За моей спиной располагается роща, в которой духи Земли воюют с тремя другими стихиями. Наведи там порядок.',''),IF(MD5(b.`QuestCompletionLog`)='11788c1b1852986fdbcbc707e735682a','Вернитесь к духу долины в Священную рощу, что на острове Лазурной Дымки.',''),0 FROM `quest_template` b WHERE b.`ID`=9450 AND (MD5(b.`LogTitle`)='299e65bc4ecc12587d5ce0ad2a39c8d7' OR MD5(b.`LogDescription`)='f8db05f5cd3da8e7d66c086968f8b1f7' OR MD5(b.`QuestDescription`)='a5c7a1fc70b3fdd1bd22d3bf0f0c16db' OR MD5(b.`QuestCompletionLog`)='11788c1b1852986fdbcbc707e735682a') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='d94b8b34d992ad3165a550e982d454c2','Зов Воды',''),IF(MD5(b.`LogDescription`)='f938d55ea0bcb9a74e1e5086b887b2f7','Наполните пустой синий бурдюк для воды в водах Астранаара в Ясеневом лесу и отнесите воду Гервдане Саэгрунд в Болотину.',''),IF(MD5(b.`QuestDescription`)='8698d19cec1276369a4f5bdeaa8eac97','Возьми этот бурдюк и отправляйся прямиком в изумрудные чащи Ясеневого леса. Среди вод, не затронутых порчей, ты найдешь деревушку Астранаар. На дне тамошнего озера лежат руины зданий, помнящих давние времена. Принеси мне образец той воды – чистой, древней и, возможно, зачарованной.\n\nЭто последнее, что мне нужно, прежде чем я отправлю тебя к Норрику.\n\nСядь на корабль в Гавани Менетилов, идущий в Аубердин. Он останавливается в Южнобережье.\n\nИ имей в виду... у леса есть глаза, и они никогда не моргают.',''),0 FROM `quest_template` b WHERE b.`ID`=94500 AND (MD5(b.`LogTitle`)='d94b8b34d992ad3165a550e982d454c2' OR MD5(b.`LogDescription`)='f938d55ea0bcb9a74e1e5086b887b2f7' OR MD5(b.`QuestDescription`)='8698d19cec1276369a4f5bdeaa8eac97') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='d94b8b34d992ad3165a550e982d454c2','Зов Воды',''),IF(MD5(b.`LogDescription`)='58876acec00c96dd0ec45fc1a480b9de','Отнесите фиал с чистейшей водой Норрику Тану Лока в Лок Модан.',''),0 FROM `quest_template` b WHERE b.`ID`=94501 AND (MD5(b.`LogTitle`)='d94b8b34d992ad3165a550e982d454c2' OR MD5(b.`LogDescription`)='58876acec00c96dd0ec45fc1a480b9de') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`);
