INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='299e65bc4ecc12587d5ce0ad2a39c8d7','Зов Земли',''),IF(MD5(b.`LogDescription`)='228b36f10cfbf8d9e67b7cd94287e5f4','Отнесите кристалл Земли Фирманваару на место крушения в долине Аммен.',''),IF(MD5(b.`QuestDescription`)='404b26c5de35866e46291400b1a2d7d5','Я передам тебе частицу моего физического облика, и ты положишь ее в основу своего тотема Земли. Отнеси эту частицу тому, кто послал тебя сюда.$b$bМы с тобой будем связаны навеки. До самой смерти силы Земли будут верно служить тебе, а отплатишь ты нам в тот миг, когда самая плоть твоя станет землей.$b$bПостарайся распорядиться своей силой мудро.',''),0 FROM `quest_template` b WHERE b.`ID`=9451 AND (MD5(b.`LogTitle`)='299e65bc4ecc12587d5ce0ad2a39c8d7' OR MD5(b.`LogDescription`)='228b36f10cfbf8d9e67b7cd94287e5f4' OR MD5(b.`QuestDescription`)='404b26c5de35866e46291400b1a2d7d5') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
