INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='f19b81b6dc61fe728b3c43984f1e4483','Новая чума',''),IF(MD5(b.`LogDescription`)='bb843fad7c8bd50641e096358a761aed','Добудьте крайне токсичный штамм у Сухожвала в руинах Лордерона для Теодора Гриффса из Подгорода.',''),IF(MD5(b.`QuestDescription`)='92759329392e33ae8c62aec4d5e2d3d6','Добро пожаловать в самый главный орган Подгорода: Квартал аптекарей! Здесь мы экспериментируем с самыми заразными и экзотическими веществами на всем Азероте.\n\nТы $gзастал:застала; меня в хорошем настроении, так что я позволю тебе поучаствовать в моем новом расследовании. Похоже, в руинах над нашим прекрасным городом завелся крайне ядовитый членистоног. Говорят, его токсин разъедает даже плоть нежити. Разве не восхитительно?\n\nНужно убедиться в достоверности этих слухов. Если эта тварь заразит тебя своим смертельным ядом, приходи ко мне – я возьму образец.',''),0 FROM `quest_template` b WHERE b.`ID`=95216 AND (MD5(b.`LogTitle`)='f19b81b6dc61fe728b3c43984f1e4483' OR MD5(b.`LogDescription`)='bb843fad7c8bd50641e096358a761aed' OR MD5(b.`QuestDescription`)='92759329392e33ae8c62aec4d5e2d3d6') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
