INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='80ec4f479bfe885e3a1d76936d503c57','Демонические планы',''),IF(MD5(b.`LogDescription`)='4b03abe5b355f85a0d91edbf7a0cf2cf','Передайте демонические планы Валуше на Заставу Расщепленного Дерева в Ясеневом лесу.',''),IF(MD5(b.`QuestDescription`)='3bf083be4fac2ddbf88057b96ebae107','Этот пергамент выронил демон, но что странно – он написан на орочьем! В нем упоминаются два имени – Диатор и Горганнон. Эти два повелителя Ужаса, пользующиеся дурной репутацией даже среди себе подобных, управляют демонами в здешних местах.$B$BВ плане подробно описывается подготовка нападения демонов на Заставу Расщепленного Дерева на северо-западе отсюда.$B$BВы уверены, что это очень заинтересует Валушу на Заставе Расщепленного Дерева.',''),0 FROM `quest_template` b WHERE b.`ID`=9535 AND (MD5(b.`LogTitle`)='80ec4f479bfe885e3a1d76936d503c57' OR MD5(b.`LogDescription`)='4b03abe5b355f85a0d91edbf7a0cf2cf' OR MD5(b.`QuestDescription`)='3bf083be4fac2ddbf88057b96ebae107') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
