INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='219336f9934849e3b115dd69f04b3aed','Зов Воздуха',''),IF(MD5(b.`LogDescription`)='10231f47603972ef5f1cc98544ba9181','Поговорите с предсказателем Нобундо в Кристальном зале Экзодара на острове Лазурной Дымки.',''),IF(MD5(b.`QuestDescription`)='4885bb3d79fe168b15f87218bab6db9f','$n, Предсказатель Нобундо спрашивал о тебе. Должно быть, настало время познать тайны воздуха, последней из стихий!$B$BЯ хочу сказать, что очень горжусь твоими достижениями. Впереди тебя ждут великие свершения.',''),0 FROM `quest_template` b WHERE b.`ID`=9547 AND (MD5(b.`LogTitle`)='219336f9934849e3b115dd69f04b3aed' OR MD5(b.`LogDescription`)='10231f47603972ef5f1cc98544ba9181' OR MD5(b.`QuestDescription`)='4885bb3d79fe168b15f87218bab6db9f') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='219336f9934849e3b115dd69f04b3aed','Зов Воздуха',''),IF(MD5(b.`LogDescription`)='10231f47603972ef5f1cc98544ba9181','Поговорите с предсказателем Нобундо в Кристальном зале Экзодара на острове Лазурной Дымки.',''),0 FROM `quest_template` b WHERE b.`ID`=9551 AND (MD5(b.`LogTitle`)='219336f9934849e3b115dd69f04b3aed' OR MD5(b.`LogDescription`)='10231f47603972ef5f1cc98544ba9181') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='219336f9934849e3b115dd69f04b3aed','Зов Воздуха',''),IF(MD5(b.`LogDescription`)='7d2f8e757f286780396c182db7009707','Поговорите с Шептателем на Штормовом Пике острова Лазурной Дымки.',''),IF(MD5(b.`QuestDescription`)='8f7fdede60c3d330ae6a1db7898dce6c','Хотя воздух неосязаем, это – могучая сила, окутывающая все вокруг и проникающая повсюду.$B$BЕго не видит око, но даже камень этой горы состоит по большей части из воздуха, воздух растворен и в морской воде, а огонь не смог бы пылать без него. Только не говори об этом другим стихиям!$B$BТот, кто может научить тебя этой мудрости, находится совсем рядом. На северном крае этого пика тебя ждет Шептатель. Благодаря ему ты познаешь суть стихии Воздуха.',''),0 FROM `quest_template` b WHERE b.`ID`=9553 AND (MD5(b.`LogTitle`)='219336f9934849e3b115dd69f04b3aed' OR MD5(b.`LogDescription`)='7d2f8e757f286780396c182db7009707' OR MD5(b.`QuestDescription`)='8f7fdede60c3d330ae6a1db7898dce6c') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='219336f9934849e3b115dd69f04b3aed','Зов Воздуха',''),IF(MD5(b.`LogDescription`)='c9ce76ef51034ffe93c9a0630bdcf58f','Отдайте Завихрение воздуха предсказателю Нобундо в Экзодаре.',''),IF(MD5(b.`QuestDescription`)='61a332f5cf4bcbf449d0d243cf7a025e','Хотя мои братья и сестры других стихий просили тебя выполнить различные задания, я ничего не хочу от тебя. Мне кажется, ты и так $gсовершил:совершила; немало, расплатившись за корабль, рухнувший в эти земли с моих небес. Я вижу, у тебя довольно мудрости, чтобы разумно распорядиться стихией воздуха.$B$BОтнеси эту часть моей сущности предсказателю Нобундо, и он поможет тебе создать тотем. Я готов отнести тебя в Экзодар по воздуху.',''),0 FROM `quest_template` b WHERE b.`ID`=9554 AND (MD5(b.`LogTitle`)='219336f9934849e3b115dd69f04b3aed' OR MD5(b.`LogDescription`)='c9ce76ef51034ffe93c9a0630bdcf58f' OR MD5(b.`QuestDescription`)='61a332f5cf4bcbf449d0d243cf7a025e') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='65bdcddf670acababba1b6917c1b89da','Зов Огня',''),IF(MD5(b.`LogDescription`)='529f969ceaf6ad49fe4ccedd839add51','Поговорите с предсказателем Нобундо в Кристальном зале Экзодара.',''),IF(MD5(b.`QuestDescription`)='6cca6025b0937785a76a2c63651cbbc9','Я рад, что ты $Gизбрал:избрала; нелегкий путь шамана. Немногие решаются на это, но я провижу, что нам не обойтись без шаманизма, который мы переняли от Сломленных.$B$BДа, теперь их называют именно так, но они некогда были дренеями. Их изменила магия Скверны, и поэтому они не могут призывать на помощь силу Света. Многие относятся к ним, а заодно и к шаманизму, с подозрением, но они не несут зла.$B$BЯ хочу, чтобы ты $gпобеседовал:побеседовала; с предсказателем Нобундо. Он – мудрейший из известных мне шаманов, и под его руководством ты многому научишься.',''),0 FROM `quest_template` b WHERE b.`ID`=9555 AND (MD5(b.`LogTitle`)='65bdcddf670acababba1b6917c1b89da' OR MD5(b.`LogDescription`)='529f969ceaf6ad49fe4ccedd839add51' OR MD5(b.`QuestDescription`)='6cca6025b0937785a76a2c63651cbbc9') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
