INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='393fc10acc2ac7bf01b522e98387df8b','Лучшая защита',''),IF(MD5(b.`LogDescription`)='5579b81e1ff3385c8e5a775783379abe','Воздаятельница Алезия с Кровавой заставы просит убить 10 сатиров, 5 разбойников и 5 скверноподанных из племени Наззивус.',''),IF(MD5(b.`QuestCompletionLog`)='6abb2475fce3b4a43198e7058d33f8e5','Вернитесь к воздаятельнице Алезии на Кровавую заставу, что на Острове Кровавой Дымки.',''),0 FROM `quest_template` b WHERE b.`ID`=9568 AND (MD5(b.`LogTitle`)='393fc10acc2ac7bf01b522e98387df8b' OR MD5(b.`LogDescription`)='5579b81e1ff3385c8e5a775783379abe' OR MD5(b.`QuestCompletionLog`)='6abb2475fce3b4a43198e7058d33f8e5') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='5cb63c4ec6a9b0b6212ee06d1fe77c9a','Приручение зверя',''),IF(MD5(b.`LogDescription`)='23d85b7c3cb65f4f205d6e1a2f5e769e','Используйте тотем приручения и приручите колючего краба. Вернитесь к охотнице Келле Тетиве Ночи.',''),IF(MD5(b.`QuestDescription`)='cf35f0052a013ea4dbcd9db4c390d881','Когда |3-6($c) избирает свой путь, $gего:ее; учат лишь убивать. Мне кажется, тебе пора сделать следующий шаг.$B$BФурболги племени Тихвой придумали, как можно приручить зверя, не тратя на это долгие месяцы. Они вырезают тотем в форме определенного животного, и он позволяет установить временную связь с существами этого вида.$B$BНачнем первый урок. Возьми этот тотем и приручи при его помощи одного из колючих крабов на западном побережье острова.',''),IF(MD5(b.`AreaDescription`)='eb2b0ba55faa1c92793a94a4764fccaf','Приручение колючего краба',''),IF(MD5(b.`QuestCompletionLog`)='2de12e09d4a07a6ace1c996026b10f07','Вернитесь к охотнице Келле Тетиве Ночи на остров Лазурной Дымки.',''),0 FROM `quest_template` b WHERE b.`ID`=9591 AND (MD5(b.`LogTitle`)='5cb63c4ec6a9b0b6212ee06d1fe77c9a' OR MD5(b.`LogDescription`)='23d85b7c3cb65f4f205d6e1a2f5e769e' OR MD5(b.`QuestDescription`)='cf35f0052a013ea4dbcd9db4c390d881' OR MD5(b.`AreaDescription`)='eb2b0ba55faa1c92793a94a4764fccaf' OR MD5(b.`QuestCompletionLog`)='2de12e09d4a07a6ace1c996026b10f07') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`),`AreaDescription`=IF(VALUES(`AreaDescription`)<>'' AND COALESCE(`quest_template_locale`.`AreaDescription`,'')='',VALUES(`AreaDescription`),`quest_template_locale`.`AreaDescription`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='5cb63c4ec6a9b0b6212ee06d1fe77c9a','Приручение зверя',''),IF(MD5(b.`LogDescription`)='1b4d5defe44831ce592bc8bf4af9b7ab','Используйте тотем приручения и приручите большого лесонога, после чего вернитесь к охотнице Келле Тетиве Ночи.',''),IF(MD5(b.`QuestDescription`)='2c4f7a12fde85f8441ef9036efa8acea','Крабы, конечно, злобные твари, но лесоног – гораздо более сложное испытание. Чем сильнее будущий союзник, тем больше стойкости требуется от охотника во время приручения.$B$BВозьми этот тотем приручения и приручи большого лесонога. Их можно найти на севере острова Лазурной Дымки.',''),IF(MD5(b.`AreaDescription`)='46e7519e6ff3cc81baf0b5145ceeafad','Приручение большого лесонога.',''),IF(MD5(b.`QuestCompletionLog`)='2de12e09d4a07a6ace1c996026b10f07','Вернитесь к охотнице Келле Тетиве Ночи на остров Лазурной Дымки.',''),0 FROM `quest_template` b WHERE b.`ID`=9592 AND (MD5(b.`LogTitle`)='5cb63c4ec6a9b0b6212ee06d1fe77c9a' OR MD5(b.`LogDescription`)='1b4d5defe44831ce592bc8bf4af9b7ab' OR MD5(b.`QuestDescription`)='2c4f7a12fde85f8441ef9036efa8acea' OR MD5(b.`AreaDescription`)='46e7519e6ff3cc81baf0b5145ceeafad' OR MD5(b.`QuestCompletionLog`)='2de12e09d4a07a6ace1c996026b10f07') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`),`AreaDescription`=IF(VALUES(`AreaDescription`)<>'' AND COALESCE(`quest_template_locale`.