INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='650f0c9617ed431d7b581a1822104265','Вторжение в Старый Стальгорн',''),IF(MD5(b.`LogDescription`)='3fd5afe019f864b6a66c7cd968862d0f','Войдите в Чертоги танов под Старым Стальгорном и добудьте голову Даргена Сокрушающий Молот.',''),IF(MD5(b.`QuestDescription`)='a019d75d0f3e8e968bed432173780a7a','Собери союзников и вместе спуститесь в пещеры под Старым Стальгорном. Там войдите в Чертоги танов и пробивайтесь к нижним склепам.\n\nПамять у меня уже не та, что прежде, но вроде одно имя я еще не забыл – Дарген Сокрушающий Молот. Скорее всего, там он за главного. Сними его голову с плеч и принеси королю Магни Бронзобороду.\n\nА, и передай заодно, что его старый друг Фарсен желает ему доброго здравия!',''),0 FROM `quest_template` b WHERE b.`ID`=96393 AND (MD5(b.`LogTitle`)='650f0c9617ed431d7b581a1822104265' OR MD5(b.`LogDescription`)='3fd5afe019f864b6a66c7cd968862d0f' OR MD5(b.`QuestDescription`)='a019d75d0f3e8e968bed432173780a7a') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='403c038b5f1594d8e52aef3d45594155','Беспокойные мертвецы',''),IF(MD5(b.`QuestDescription`)='8fc735e3b7635af4e5410d011c017a20','Могилы в Чертогах танов чем-то потревожены... какие-то странные звуки доносятся из самых глубин склепов. Духи мертвых спят чутко, и, вероятно, там произошло нечто, что испугало их.\n\nОтправляйся туда и посмотри, что можно сделать. Если какие-то мертвецы и вправду пробудились – что ж, придется тебе упокоить их снова!',''),0 FROM `quest_template` b WHERE b.`ID`=96394 AND (MD5(b.`LogTitle`)='403c038b5f1594d8e52aef3d45594155' OR MD5(b.`QuestDescription`)='8fc735e3b7635af4e5410d011c017a20') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='02cf9519cf13db58dd6e4fea687fb018','Давняя обида',''),IF(MD5(b.`LogDescription`)='9eff0fb69067d65c9825dfff890ad187','Помогите обрести покой духу Фалдрима Старая Наковальня и вернитесь к призрачной слуге в Чертоги танов.',''),0 FROM `quest_template` b WHERE b.`ID`=96395 AND (MD5(b.`LogTitle`)='02cf9519cf13db58dd6e4fea687fb018' OR MD5(b.`LogDescription`)='9eff0fb69067d65c9825dfff890ad187') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='043feb855a26fd2c0983b9d7b771ba5a','Важные реликвии',''),IF(MD5(b.`QuestDescription`)='d53440d095cd60903fcd4232b92de126','Эй, $gискатель:искательница; приключений!.. Мне очень нужна твоя помощь.\n\nЕдва я успел сюда проникну... то есть начать патрулирование, как на буровых машинах приехали дворфы Черного Железа! Не знаю, зачем они тут, но на кону бесценная добыча... вернее, "важные культурные ценности"! Прошу, принеси мне все реликвии, которые тебе попадутся.\n\nУверяю, мы все внесем в каталог и поместим на почетное место.',''),0 FROM `quest_template` b WHERE b.`ID`=96403 AND (MD5(b.`LogTitle`)='043feb855a26fd2c0983b9d7b771ba5a' OR MD5(b.`QuestDescription`)='d53440d095cd60903fcd4232b92de126') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
