INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='ea9f748b154f2ae196669769610e2e6f','Ковка оружия',''),IF(MD5(b.`LogDescription`)='9a26580b55bb98b34a4a1e0794bba875','Принесите ящик с материалами Бемаррину в Луносвет.',''),IF(MD5(b.`QuestDescription`)='24f8b5c406d422b86f22434f10fcb103','Что ж, ты $gдоказал:доказала;, что $gдостоин:достойна; стать рыцарем нашего ордена. Для меня большая честь даровать тебе титул адепта, $n. Сам принц Кель''тас гордился бы тобой.$B$BТы будешь опорой для тех, кто сражается рядом с тобой, и примером для тех, кто стремится присоединиться к нам. Не щади врагов и не показывай свою слабость, защищай свой народ и стань истинным владыкой Света.$B$BА теперь пришло время выковать оружие, положенное тебе с новым титулом.',''),0 FROM `quest_template` b WHERE b.`ID`=9707 AND (MD5(b.`LogTitle`)='ea9f748b154f2ae196669769610e2e6f' OR MD5(b.`LogDescription`)='9a26580b55bb98b34a4a1e0794bba875' OR MD5(b.`QuestDescription`)='24f8b5c406d422b86f22434f10fcb103') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
