INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='dafcb4967d3660b818358d985d2864ac','Призыв леди Лиадрин',''),IF(MD5(b.`LogDescription`)='d69557dcdd3b0d374bd9fe33a4b36d9d','Поговорите с Лордом Соланаром в Луносвете.',''),IF(MD5(b.`QuestDescription`)='4aae4894a87889af1c953d8f15f6f208','Твоя преданность ордену не осталась незамеченной: Лорд Соланар Кровогнев, правая рука самой Леди Лиадрин, пожелал встретиться с тобой.$B$BТакой чести удостаиваются немногие, $n. Обычно новыми кандидатами занимаюсь я, но Лорд Соланар считает, что ты – $gособенный:особенная;. Не упусти свой шанс, $n!',''),0 FROM `quest_template` b WHERE b.`ID`=9721 AND (MD5(b.`LogTitle`)='dafcb4967d3660b818358d985d2864ac' OR MD5(b.`LogDescription`)='d69557dcdd3b0d374bd9fe33a4b36d9d' OR MD5(b.`QuestDescription`)='4aae4894a87889af1c953d8f15f6f208') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='f07837a567cbe2528acca979855a0d88','Путь мастера',''),IF(MD5(b.`LogDescription`)='0c5e61d0aba8a17ed7e3f96851117b6c','Поговорите с Лордом Соланаром еще раз и примите предложение о покровительстве.',''),IF(MD5(b.`QuestDescription`)='d0a1fe5bd086e1baf3f15c71405b4d3d','В нашем ордене есть круг посвященных, в который входят только самые преданные, опытные и умелые рыцари. Отличить их можно по особой породе скакунов – талассийским скакунам.$B$BКаждый кандидат на титул мастера должен доказать свою верность идеалам ордена и заручиться поддержкой одного из посвященных.$B$BЕсли ты действительно желаешь стать мастером – я лично буду твоим покровителем.',''),0 FROM `quest_template` b WHERE b.`ID`=9722 AND (MD5(b.`LogTitle`)='f07837a567cbe2528acca979855a0d88' OR MD5(b.`LogDescription`)='0c5e61d0aba8a17ed7e3f96851117b6c' OR MD5(b.`QuestDescription`)='d0a1fe5bd086e1baf3f15c71405b4d3d') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
