INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='470da6a335e47ca6943a6884769eeb93','Основы походной жизни: снятие шкур',''),IF(MD5(b.`LogDescription`)='25785df89bbfb9b7f9dcb9f515474e50','Поговорите с Рэндом Робартом на дороге из Брилла в Подгород, чтобы показать свои навыки и научиться создавать предмет для лагеря, соответствующий вашей профессии.',''),IF(MD5(b.`QuestDescription`)='341311bedbfb45e4e6fd815e28e59aad','Способность умело снимать с убитых зверей кожи и шкуры – один из наиболее полезных навыков для любого искателя приключений. Сдается мне, я знаю кое-кого, кто может научить тебя создавать лагерный стул для твоего лагеря. Иногда очень важно, чтобы было где расслабиться, а из шкур, которые ты собираешь, можно изладить очень удобное место для сидения. Благодаря этому ты точно будешь в форме, когда придет время для следующей потасовки.',''),0 FROM `quest_template` b WHERE b.`ID`=97960 AND (MD5(b.`LogTitle`)='470da6a335e47ca6943a6884769eeb93' OR MD5(b.`LogDescription`)='25785df89bbfb9b7f9dcb9f515474e50' OR MD5(b.`QuestDescription`)='341311bedbfb45e4e6fd815e28e59aad') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`);
