INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='fd378ebb95f0d3d082ec542eed19d75a','Последние реагенты',''),IF(MD5(b.`LogDescription`)='738449d9ff03e8b14e21c22fabdd7af7','Принесите 5 сущностей прыгуаны-охотника и 30 ягод тероккарской черной рябины Кокореку в Гнездовье Литик.',''),IF(MD5(b.`QuestDescription`)='e320c0f0e6db3bfd2091ee03a577d842','Я могу изготовить предмет, который нейтрализует охранные заклинания Гнездовья Шалас. Но предупреждаю, $n – магия будет действовать только пока вашего друга удерживают в плену. Я не стану добровольно давать вам средства для нападения на мой народ.$B$BУ меня есть почти все нужные материалы, но кое-что придется добыть вам. Мне потребуются сущности прыгуаны-охотника и горсть тероккарской черной рябины. Все это можно найти поблизости от Гнездовья.',''),IF(MD5(b.`QuestCompletionLog`)='908ea37cf179863f42b2a583e424166d','Вернитесь к Кокореку в Гнездовье Литик, что в лесу Тероккар.',''),0 FROM `quest_template` b WHERE b.`ID`=9969 AND (MD5(b.`LogTitle`)='fd378ebb95f0d3d082ec542eed19d75a' OR MD5(b.`LogDescription`)='738449d9ff03e8b14e21c22fabdd7af7' OR MD5(b.`QuestDescription`)='e320c0f0e6db3bfd2091ee03a577d842' OR MD5(b.`QuestCompletionLog`)='908ea37cf179863f42b2a583e424166d') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
