nLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='64a2f86fabf1cf4454a9896d61995c87','Изначальная магия',''),IF(MD5(b.`LogDescription`)='2d19e7f3cf383cbbb28c0d162c38973f','Используйте талисман Кокорека возле тотемов, охраняющих завесу Шалас, после чего поговорите с геологом Бальморалом.',''),IF(MD5(b.`QuestDescription`)='e3af878c6eb784a59aa747c2b18abdb8','Я заключил заклинание в этот талисман. Выпустите его рядом с охранными тотемами на подходе к Гнездовью Шалас – этого должно хватить для снятия защиты.$B$B<Вы обращаете внимание на то, что фигурка в талисмане совсем не похожа на араккоа>$B$BМой народ не всегда выглядел так, как сейчас. Когда-то мы были великолепными созданиями, но... слишком много раз сделали неправильный выбор, и провалили свою священную миссию. Это стоило нам нашей красоты, нашей силы и едва ли не всей нашей жизни. Не повторяйте наших ошибок, $n.',''),IF(MD5(b.`QuestCompletionLog`)='4749080aceec6d7ee4dc8790733abdb1','Вернитесь к геологу Бальморалу в лес Тероккар.',''),0 FROM `quest_template` b WHERE b.`ID`=9975 AND (MD5(b.`LogTitle`)='64a2f86fabf1cf4454a9896d61995c87' OR MD5(b.`LogDescription`)='2d19e7f3cf383cbbb28c0d162c38973f' OR MD5(b.`QuestDescription`)='e3af878c6eb784a59aa747c2b18abdb8' OR MD5(b.`QuestCompletionLog`)='4749080aceec6d7ee4dc8790733abdb1') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='64a2f86fabf1cf4454a9896d61995c87','Изначальная магия',''),IF(MD5(b.`LogDescription`)='587b49c8cabf562b1e7395510a963a9b','Используйте талисман Кокорека возле тотемов, охраняющих завесу Шалас, после чего поговорите с наблюдателем Нодаком.',''),IF(MD5(b.`QuestDescription`)='e3af878c6eb784a59aa747c2b18abdb8','Я заключил заклинание в этот талисман. Выпустите его рядом с охранными тотемами на подходе к Гнездовью Шалас – этого должно хватить для снятия защиты.$B$B*Вы обращаете внимание на то, что фигурка в талисмане совсем не похожа на араккоа*$B$BМой народ не всегда выглядел так, как сейчас. Когда-то мы были великолепными созданиями, но... слишком много раз сделали неправильный выбор, и провалили свою священную миссию. Это стоило нам нашей красоты, нашей силы и едва ли не всей нашей жизни. Не повторяйте наших ошибок, $n.',''),IF(MD5(b.`QuestCompletionLog`)='1a0218dcac47828e923a462c10b63d04','Вернитесь к наблюдателю Нодаку в горы Скетил, что в лесу Тероккар.',''),0 FROM `quest_template` b WHERE b.`ID`=9976 AND (MD5(b.`LogTitle`)='64a2f86fabf1cf4454a9896d61995c87' OR MD5(b.`LogDescription`)='587b49c8cabf562b1e7395510a963a9b' OR MD5(b.`QuestDescription`)='e3af878c6eb784a59aa747c2b18abdb8' OR MD5(b.`QuestCompletionLog`)='1a0218dcac47828e923a462c10b63d04') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`),`QuestCompletionLog`