INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='3069b1d791cce4adcde765b2ef609107','Спасите Дейрома!',''),IF(MD5(b.`LogDescription`)='478346d38e4d70050500003a469eb56c','Проберитесь в гнездовье Шалас, убейте Луангу и освободите Дейрома, после чего доложитесь Леди Дене Кеннеди в Бастионе Аллерии.',''),IF(MD5(b.`QuestDescription`)='3ad66b8de0d824612ec7350f24f989da','Как можно быстрее отправляйтесь в завесу Шалас, $n! Время не терпит. Когда араккоа прознают, что вы сделали с их защитой, они попытаются перевезти Дейрома в другое место или даже убить его!$B$BЕсли можете, возьмите с собой друга, или даже двоих – вам там придется нелегко. Эти птицелюди очень дорожат пленником, и просто так с ним не расстанутся. Когда найдете Дейрома и расправитесь с его похитителями, возвращайтесь в Бастион Аллерии и поговорите с Тандером.',''),IF(MD5(b.`QuestCompletionLog`)='b83408c07fb1a50381b5f136e99b3d62','Вернитесь к леди Дене Кеннеди в Бастион Аллерии, что в лесу Тероккар.',''),0 FROM `quest_template` b WHERE b.`ID`=9980 AND (MD5(b.`LogTitle`)='3069b1d791cce4adcde765b2ef609107' OR MD5(b.`LogDescription`)='478346d38e4d70050500003a469eb56c' OR MD5(b.`QuestDescription`)='3ad66b8de0d824612ec7350f24f989da' OR MD5(b.`QuestCompletionLog`)='b83408c07fb1a50381b5f136e99b3d62') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')='',VALUES(`QuestCompletionLog`),`quest_template_locale`.`QuestCompletionLog`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`QuestCompletionLog`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`LogTitle`)='d0c43111a245e820b20fc579cc59202a','Спасите Дугара!',''),IF(MD5(b.`LogDescription`)='60397c4608ef2741ac5240d8491a4260','Проберитесь в завесу Шалас, убейте Луангу и освободите Дейрома, после чего доложитесь Рокагу в Форте Камнеломов.',''),IF(MD5(b.`QuestDescription`)='2750ce622d244834fb4297e3e45c8b18','Как можно быстрее отправляйтесь в завесу Шалас, $n! Время не терпит. Когда араккоа прознают, что вы сделали с их защитой, они попытаются перевезти Дугара в другое место или даже убить его!$B$BЕсли можете, возьмите с собой друга, или даже двоих – вам там придется нелегко. Эти птицелюди очень дорожат пленником, и просто так с ним не расстанутся. Когда найдете Дугара и расправитесь с его похитителями, возвращайтесь в Форт Камнеломов и поговорите с Рокагом.',''),IF(MD5(b.`QuestCompletionLog`)='e2008e3a3c43f18d83fa13809388919e','Вернитесь к Рокагу в лес Тероккар.',''),0 FROM `quest_template` b WHERE b.`ID`=9981 AND (MD5(b.`LogTitle`)='d0c43111a245e820b20fc579cc59202a' OR MD5(b.`LogDescription`)='60397c4608ef2741ac5240d8491a4260' OR MD5(b.`QuestDescription`)='2750ce622d244834fb4297e3e45c8b18' OR MD5(b.`QuestCompletionLog`)='e2008e3a3c43f18d83fa13809388919e') ON DUPLICATE KEY UPDATE `LogTitle`=IF(VALUES(`LogTitle`)<>'' AND COALESCE(`quest_template_locale`.`LogTitle`,'')='',VALUES(`LogTitle`),`quest_template_locale`.`LogTitle`),`LogDescription`=IF(VALUES(`LogDescription`)<>'' AND COALESCE(`quest_template_locale`.`LogDescription`,'')='',VALUES(`LogDescription`),`quest_template_locale`.`LogDescription`),`QuestDescription`=IF(VALUES(`QuestDescription`)<>'' AND COALESCE(`quest_template_locale`.`QuestDescription`,'')='',VALUES(`QuestDescription`),`quest_template_locale`.`QuestDescription`),`QuestCompletionLog`=IF(VALUES(`QuestCompletionLog`)<>'' AND COALESCE(`quest_template_locale`.`QuestCompletionLog`,'')=